insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_64e5966e2435','Bay is the ONLY base coat color that has black points.','["True","False"]'::jsonb,'True','colors','base-coat-colors','easy',null,'Correct. Only bay horses show black mane, tail, and lower legs. Chestnut has red points; black has no color contrast at all.','Not quite. Bay is indeed the only base coat color defined by black points.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_92c7d9eba1bc','What is the defining characteristic of a bay horse?','["A golden body with a white mane","A reddish-brown body with black mane, tail, and lower legs","A completely black coat with no brown tones","A chestnut body with a flaxen mane"]'::jsonb,'A reddish-brown body with black mane, tail, and lower legs','colors','common-horse-colors','easy',null,'Correct. Bay horses have a reddish-brown body with black points — the mane, tail, and lower legs are always black.','The defining feature of bay is the black points. Look for a reddish-brown body paired with a black mane, tail, and lower legs.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_ad52efcc8851','What separates a black horse from a very dark bay?','["Black horses have no brown or reddish tones anywhere on the body","Black horses always have a white mane","Black horses are larger than bay horses","Black horses only appear in thoroughbreds"]'::jsonb,'Black horses have no brown or reddish tones anywhere on the body','colors','common-horse-colors','easy',null,'Correct. A true black horse shows no brown or reddish coloring anywhere — body, mane, tail, and legs are all solid black.','Check the body for any brown or reddish tones. If they are present, the horse is bay, not black.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_8ba0383f005f','A chestnut horse differs from a bay horse because:','["Chestnut horses never have black in the mane or tail","Chestnut horses always have white legs","Chestnut horses are always darker than bay","Chestnut horses have blue eyes"]'::jsonb,'Chestnut horses never have black in the mane or tail','colors','common-horse-colors','easy',null,'Correct. Chestnut horses have a red or reddish-brown coat with a mane and tail in the same color family — never black.','The key difference is the mane and tail. Chestnut horses have no black in their mane or tail. Bay horses do.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_3065ed8b21ea','Sorrel is best described as:','["A lighter, brighter copper-red chestnut","A very dark reddish-brown horse","A golden horse with a white mane","A gray horse with red tones"]'::jsonb,'A lighter, brighter copper-red chestnut','colors','common-horse-colors','easy',null,'Correct. Sorrel refers to a lighter, more copper or golden-red tone — a variation of chestnut common in stock breeds.','Sorrel is the lighter, more copper-toned end of the chestnut spectrum.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_d17b1fc48284','Liver chestnut is best described as:','["A very dark, deep reddish-brown coat with no black","A chestnut horse with black legs only","A gray horse with reddish tones","A palomino with a dark mane"]'::jsonb,'A very dark, deep reddish-brown coat with no black','colors','common-horse-colors','easy',null,'Correct. Liver chestnut is the darkest variation of chestnut — deeply reddish-brown, sometimes appearing nearly chocolate. No black anywhere.','Liver chestnut is chestnut at its darkest — the coat appears very deep reddish-brown or chocolate, still without any black.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_63d321478cc5','Which color group contains red pigment only — with no black anywhere?','["Chestnut, sorrel, and liver chestnut","Bay and black","Palomino and buckskin","Gray and roan"]'::jsonb,'Chestnut, sorrel, and liver chestnut','colors','common-horse-colors','easy',null,'Correct. Chestnut, sorrel, and liver chestnut are all red-pigment based with no black in the mane, tail, or body.','The red-based colors — chestnut, sorrel, and liver chestnut — never have black hairs.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_3d0ee21a81d8','What gene produces the palomino coat color?','["One copy of the cream gene on a chestnut base","Two copies of the dun gene","One copy of the gray gene","The roan gene on a bay base"]'::jsonb,'One copy of the cream gene on a chestnut base','colors','common-horse-colors','easy',null,'Correct. Palomino results from one copy of the cream gene acting on a chestnut base, lightening the red pigment to gold.','Palomino is produced by the cream gene — specifically one copy of it — working on a chestnut base.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_9658f228a9bd','What is the single clearest difference between palomino and buckskin?','["Palomino has a white mane; buckskin has a black mane","Palomino is taller","Buckskin has white markings; palomino does not","Palomino horses are always darker"]'::jsonb,'Palomino has a white mane; buckskin has a black mane','colors','common-horse-colors','easy',null,'Correct. Both are golden-bodied horses, but palomino has a white or cream mane and tail, while buckskin has black points.','The mane and tail tell the story. White or cream = palomino. Black = buckskin.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_83e348fcbc12','A dun horse is most reliably identified by:','["A dorsal stripe running along the spine","A very light body with a dark mane only","White patches on the hindquarters","A mane that is always white"]'::jsonb,'A dorsal stripe running along the spine','colors','common-horse-colors','easy',null,'Correct. The dorsal stripe — a dark line running from mane to tail along the spine — is the defining feature of dun.','Look for the dorsal stripe. A dark line along the spine is the clearest sign of dun.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_4aca70350548','Flaxen describes:','["A chestnut horse with a noticeably lighter or cream mane and tail","A palomino horse with a dark body","A buckskin without black points","A gray horse with golden tones"]'::jsonb,'A chestnut horse with a noticeably lighter or cream mane and tail','colors','common-horse-colors','easy',null,'Correct. Flaxen is a modifier that lightens only the mane and tail of a chestnut horse — the body stays chestnut.','Flaxen applies to chestnut horses where the mane and tail are noticeably lighter than the body.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_7bbce16f8354','How does dun differ from palomino or buckskin?','["Dun horses show a dorsal stripe; palomino and buckskin do not","Dun horses are always gray","Palomino horses have a dorsal stripe","Dun horses have blue eyes"]'::jsonb,'Dun horses show a dorsal stripe; palomino and buckskin do not','colors','common-horse-colors','easy',null,'Correct. If you see a golden horse with a dark line along the spine, it is dun. Palomino and buckskin lack this stripe.','The dorsal stripe is the giveaway. Palomino and buckskin are golden but have no stripe down the back.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_ec7fbb6af94f','What color is a gray horse born with?','["A base color such as bay, black, or chestnut — gray horses lighten over time","Gray or white from birth","Pure white with pink skin","Silver with blue eyes"]'::jsonb,'A base color such as bay, black, or chestnut — gray horses lighten over time','colors','common-horse-colors','easy',null,'Correct. Gray horses are born with a base color and progressively lighten as the gray gene causes pigment loss in the hair follicles.','Gray horses are not born gray. They are born with a base color and lighten progressively with age.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_0a3b6a888fe9','How is a gray horse different from a white horse?','["Gray horses have dark skin and lighten over time; white horses are born white with pink skin","White horses are older grays","Gray horses have blue eyes; white horses do not","There is no difference"]'::jsonb,'Gray horses have dark skin and lighten over time; white horses are born white with pink skin','colors','common-horse-colors','easy',null,'Correct. The easiest distinction: gray horses are born with color, have dark skin, and lighten with age. True white horses are born white and have pink skin.','Skin color is a reliable clue. Gray horses have dark skin; white horses have pink skin. Also, gray horses lighten with age while white horses stay white.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_208e9732f336','Dapple gray refers to:','["A gray horse showing circular patterns of lighter and darker grey across the body","A gray horse with colored spots on the face","A roan horse with gray tones","A white horse with gray flecks"]'::jsonb,'A gray horse showing circular patterns of lighter and darker grey across the body','colors','common-horse-colors','easy',null,'Correct. Dapple gray is a middle stage of graying. It shows ring-like light areas with darker gray around them, often on the hindquarters and back.','Dapples are circular patterns that can appear on gray horses during the middle stage of graying.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_bc871aee164b','Flea-bitten gray describes:','["A light or nearly white coat speckled with small pigmented flecks","A dark gray with solid black patches","A roan pattern on a gray horse","A young gray horse before it dapples"]'::jsonb,'A light or nearly white coat speckled with small pigmented flecks','colors','common-horse-colors','easy',null,'Correct. Flea-bitten gray occurs in older gray horses — the coat has mostly lightened but shows small specks or clusters of pigmented hairs throughout.','Flea-bitten gray is the later stage — a nearly white coat dotted with small dark specks of remaining pigment.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_66214f84b3ae','What makes a roan coat different from a gray coat?','["Roan horses do not progressively lighten with age and keep a solid-colored head","Roan horses are always lighter than gray","Roan horses have pink skin","Roan horses are born white"]'::jsonb,'Roan horses do not progressively lighten with age and keep a solid-colored head','colors','common-horse-colors','easy',null,'Correct. Roan coats are stable throughout the horse''s life and the head stays solid-colored. Gray horses progressively lighten and white hairs spread across the whole body including the head.','The two key roan identifiers: the coat stays relatively stable (no progressive lightening) and the head remains the base color.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_6cf225851311','Strawberry roan is produced by:','["White hairs evenly mixed into a chestnut base coat","A black base with reddish tones","A bay base with cream dilution","A gray base with white hairs"]'::jsonb,'White hairs evenly mixed into a chestnut base coat','colors','common-horse-colors','easy',null,'Correct. Strawberry roan is a chestnut base with white hairs evenly mixed through the body, giving a pinkish-red appearance.','Strawberry roan starts from a chestnut or sorrel base — the roan pattern mixes white hairs evenly through the red body coat.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_c195f133a6a7','Blue roan gets its blue-grey appearance from:','["White hairs mixed into a black base coat","A dilute gene on a gray horse","White patches on a dark body","A cream gene on a bay horse"]'::jsonb,'White hairs mixed into a black base coat','colors','common-horse-colors','easy',null,'Correct. Blue roan is a black base coat with white hairs evenly mixed through the body, creating a cool blue-grey appearance.','Blue roan = black base + roan gene. The mix of black and white hairs produces the characteristic blue-grey effect.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_8109fe7f9c73','A roan horse typically has a solid-colored head. Why is this important for identification?','["It distinguishes roan from gray, where white spreads to the head","It shows the horse is young","It means the horse has no base color","It indicates the horse has two roan parents"]'::jsonb,'It distinguishes roan from gray, where white spreads to the head','colors','common-horse-colors','easy',null,'Correct. The solid-colored head is the fastest visual check to separate roan from gray — gray horses lighten across the entire body including the face.','If the head is still solid-colored but the body looks mixed, it is roan. If white has spread to the face and body both, it is gray.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_2fae8e0c7815','What defines a pinto coat pattern?','["Large white patches over a base-colored coat","Small spots distributed across the body","A single-colored body with a white mane","A striped pattern on the legs and back"]'::jsonb,'Large white patches over a base-colored coat','colors','common-horse-colors','easy',null,'Correct. Pinto is a pattern of large, irregular white patches over a base-colored coat.','Pinto horses show large white patches — not small spots — over their base color.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_48932dc5be19','Tobiano pinto is most easily identified by:','["White patches crossing the topline from back to hindquarters","White patches only on the belly and sides","A completely white body with colored patches","Colored spots on a white background"]'::jsonb,'White patches crossing the topline from back to hindquarters','colors','common-horse-colors','easy',null,'Correct. If white crosses the horse''s back, it is most likely tobiano. The legs are often white and patch edges are rounded.','Tobiano''s key feature: white crosses the topline (the back and hindquarters). That is the fastest way to identify it.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_c6341605d77a','What distinguishes overo pinto from tobiano?','["White rarely crosses the topline in overo; it spreads from the belly upward","Overo horses always have four white legs","Tobiano has irregular patch edges; overo has smooth edges","There is no difference — the terms are interchangeable"]'::jsonb,'White rarely crosses the topline in overo; it spreads from the belly upward','colors','common-horse-colors','easy',null,'Correct. Overo white patches spread horizontally from the belly upward and rarely cross the spine, giving a different overall look from tobiano.','Tobiano white crosses the back. Overo white stays on the sides and belly — rarely crossing the topline.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_cc52250809d7','Which identifying feature appears on all Appaloosa horses regardless of coat pattern?','["Mottled skin, visible white sclera, and striped hooves","A dorsal stripe along the spine","A white blanket on the hindquarters only","Blue eyes and a white mane"]'::jsonb,'Mottled skin, visible white sclera, and striped hooves','colors','common-horse-colors','easy',null,'Correct. These three characteristics — mottled skin around the muzzle and eyes, visible white sclera (the part around the iris), and striped hooves — are present in all Appaloosa horses.','Look beyond the coat: mottled skin, a visible white ring around the eye, and striped hooves all identify Appaloosa regardless of the specific pattern.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_44d012c6a38f','What does a Blanket Appaloosa pattern mean?','["A white patch over the hindquarters, sometimes with dark spots within it","White patches on the chest and forehead only","A completely white horse with colored legs","Spots scattered evenly across the entire body"]'::jsonb,'A white patch over the hindquarters, sometimes with dark spots within it','colors','common-horse-colors','easy',null,'Correct. A Blanket Appaloosa pattern has a distinct white area over the hindquarters. It may be solid white or have dark spots inside it.','The Blanket Appaloosa pattern has a white area that covers the hindquarters. It may or may not have spots within it.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_077a35a472e8','What is a Leopard Appaloosa?','["A mostly white body covered in dark spots across the coat","A bay horse with a white blanket","A pinto horse with irregular patches","A gray horse with dark speckling"]'::jsonb,'A mostly white body covered in dark spots across the coat','colors','common-horse-colors','easy',null,'Correct. Leopard Appaloosa is the most striking Appaloosa pattern - a predominantly white body with dark spots distributed across the coat, similar to a leopard.','Leopard Appaloosa is the boldest Appaloosa pattern: a white base covered in dark, rounded spots across the body.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_e8b03ac93c16','A horse has a golden body, a white mane, and no dark points. What color is it?','["Palomino","Buckskin","Dun","Gray"]'::jsonb,'Palomino','colors','common-horse-colors','easy',null,'Correct. Golden body + white or cream mane and tail = palomino. No black points present.','If the body is golden and the mane is white or cream — not black — the horse is palomino.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_02d0c8b8b25e','A horse has a golden body, a black mane, and black lower legs. What color is it?','["Buckskin","Palomino","Dun","Sorrel"]'::jsonb,'Buckskin','colors','common-horse-colors','easy',null,'Correct. Golden body + black mane, tail, and legs = buckskin. The black points are the key.','If the body is golden but the mane and legs are black, it is buckskin — not palomino.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_0b48bd449190','A horse has a tan body, a dark dorsal stripe, and light leg barring. What color is it?','["Dun","Buckskin","Palomino","Gray"]'::jsonb,'Dun','colors','common-horse-colors','easy',null,'Correct. A tan or sandy body with a dorsal stripe and possible leg barring = dun. These primitive markings are the defining feature.','The dorsal stripe is the key clue. A golden or tan horse with a stripe down the spine is dun, not buckskin or palomino.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_14e301ee3d76','Why is coat color important to record in breed registration documents?','["It is a permanent, visible feature used to identify an individual horse","It determines the horse''s sale price","It shows the horse''s training level","It predicts performance ability"]'::jsonb,'It is a permanent, visible feature used to identify an individual horse','colors','common-horse-colors','easy',null,'Correct. Coat color is recorded because it is a stable, visible characteristic that helps identify and distinguish one horse from another.','Color is recorded for identification purposes — it is a permanent feature that helps confirm which horse a document belongs to.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_52cda12c90d6','What two base pigments produce all horse coat colors?','["Red (phaeomelanin) and black (eumelanin)","Yellow and brown","White and grey","Gold and silver"]'::jsonb,'Red (phaeomelanin) and black (eumelanin)','colors','common-horse-colors','easy',null,'Correct. All horse coat colors are produced by combinations, dilutions, and modifications of just two pigments: red and black.','Every horse coat color comes from red pigment, black pigment, or a combination of both.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_069e9321c1d5','Which of these colors has NO black pigment anywhere?','["Chestnut","Bay","Blue roan","Buckskin"]'::jsonb,'Chestnut','colors','common-horse-colors','easy',null,'Correct. Chestnut horses carry only red pigment — there is no black anywhere in the coat, mane, or tail.','Chestnut is the red-only color. Bay, blue roan, and buckskin all involve some black pigment.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_d4ea07c105f6','A horse has white patches with jagged, irregular edges that spread from the belly up and do not cross the back. What pinto pattern is this?','["Overo","Tobiano","Blanket Appaloosa","Leopard Appaloosa"]'::jsonb,'Overo','colors','common-horse-colors','easy',null,'Correct. Jagged patch edges, spreading from the belly upward without crossing the topline = overo.','When white stays on the sides and belly without crossing the back, and the patches have irregular edges, it is overo.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_81637440206f','A horse''s coat is a mix of white and chestnut hairs throughout the body, but the head and lower legs are solid chestnut. What color is it?','["Strawberry Roan","Dapple Gray","Flea-Bitten Gray","Palomino"]'::jsonb,'Strawberry Roan','colors','common-horse-colors','easy',null,'Correct. White hairs mixed evenly through a chestnut body, with a solid chestnut head = strawberry roan.','Even white hair mixing through a chestnut body — with the head staying solid chestnut — is strawberry roan.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_427c2b3fc90f','Identify the coat color in the photo.','["Bay","Chestnut","Black","Buckskin"]'::jsonb,'Bay','colors','common-horse-colors','easy','/courses/schooling-ring/colors-markings/common-horse-colors/images/the-viewing-room/bay.png','Correct. Bay: reddish-brown body with a black mane, tail, and lower legs.','Look at the mane and legs. If they are black on a reddish-brown body, it is bay.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_0abbde4a7a27','Identify the coat color in the photo.','["Palomino","Buckskin","Dun","Chestnut"]'::jsonb,'Palomino','colors','common-horse-colors','easy','/courses/schooling-ring/colors-markings/common-horse-colors/images/the-viewing-room/palomino.png','Correct. Golden body with a white or cream mane and tail = palomino.','If the mane and tail are white or cream on a golden body, it is palomino.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_99f1445e2de9','Identify the coat color in the photo.','["Dapple Gray","Roan","Flea-Bitten Gray","Appaloosa"]'::jsonb,'Dapple Gray','colors','common-horse-colors','easy','/courses/schooling-ring/colors-markings/common-horse-colors/images/common-horse-colors/dapple-gray.png','Correct. The circular dapple patterns — rings of lighter and darker grey — identify this as dapple gray.','Look for the distinctive ring-shaped lighter patches over a grey body. That is dapple gray.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_78feb9f4d815','What is the defining characteristic of a blaze compared to a strip?','["It runs from the forehead to the chin only","It is wide enough to cover the nasal bones from side to side","It always includes a snip on the muzzle","It only appears on gray or white horses"]'::jsonb,'It is wide enough to cover the nasal bones from side to side','markings','face-markings','easy',null,'Correct. A blaze spans the full width of the nasal bones. A strip is narrower and does not reach the edges.','Not quite. The key difference is width: a blaze covers the nasal bones edge to edge, while a strip does not reach the sides.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_bca5414fcf33','A horse has a white patch on its forehead and a small white area on its muzzle, with no white connecting them. How is this described?','["Blaze","Strip and blaze","Star and snip","Extended blaze"]'::jsonb,'Star and snip','markings','face-markings','easy',null,'Correct. When the two white areas are separated by dark hair, they are named individually: star and snip.','Not quite. A forehead marking is a star, and a muzzle marking is a snip. If they do not connect, name both separately.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_a4e2255be51e','Where on the face is a snip located?','["Between or around the nostrils on the muzzle","Between the eyes on the forehead","On the cheek below the eye","Running down the center of the nose"]'::jsonb,'Between or around the nostrils on the muzzle','markings','face-markings','easy',null,'Correct. A snip is a white patch found between or around the nostrils on the lower muzzle.','Not quite. A snip sits on the muzzle, usually between or around the nostrils.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_ab132cade7b0','Why are face markings recorded on registration papers and health certificates?','["They indicate breeding potential","They are a permanent, visible feature used to identify individual horses","They are required by insurance companies only","They show which bloodline a horse belongs to"]'::jsonb,'They are a permanent, visible feature used to identify individual horses','markings','face-markings','easy',null,'Correct. Face markings are useful because they are visible, lasting, and individual to the horse.','Face markings are recorded for identification. They help people describe and confirm an individual horse.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_764a75f432f3','A narrow white line down the center of the face is usually called a:','["Strip","Bald face","Snip","Chin spot"]'::jsonb,'Strip','markings','face-markings','easy',null,'Correct. A strip is a narrow white marking running down the face.','Look for the long, narrow shape down the nose. That is a strip.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_af3d61efb658','A white marking between the eyes on the forehead is usually called a:','["Star","Snip","Bald face","Apron face"]'::jsonb,'Star','markings','face-markings','easy',null,'Correct. A star is located on the forehead between the eyes.','The forehead area between the eyes is where a star is found.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_40407a1c4027','When a star, strip, and snip are all present, what should the description include?','["Only the largest marking","Only the marking closest to the muzzle","All visible parts of the marking","Only the color of the horse"]'::jsonb,'All visible parts of the marking','markings','face-markings','easy',null,'Correct. Naming all visible parts gives the clearest description.','Use all the visible marking terms so the description is complete.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_7637c9248748','Which marking is most likely to involve pink skin around the eyes and muzzle?','["Bald face","Tiny star","Faint snip","Narrow strip"]'::jsonb,'Bald face','markings','face-markings','easy',null,'Correct. A bald face has a large amount of white and often includes pink skin around broad areas of the face.','The most extensive white marking is the bald face, so it is most likely to include pink skin around the eyes and muzzle.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_e14df45e2efd','True or false: A chin spot is found on or under the chin area.','["True","False"]'::jsonb,'True','markings','face-markings','easy',null,'Correct. A chin spot is a small white mark on or under the chin area.','Not quite. A chin spot sits on or under the chin area.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_4e4e40fd4c2e','If white hair connects a star to a strip, how should you think about the marking?','["As two different face markings that are listed as connected.","As a leg marking","As no marking","As a coat color"]'::jsonb,'As two different face markings that are listed as connected.','markings','face-markings','easy',null,'Correct. Both are identified separately, but described as connected.','If the white connects, describe the connected parts together, but both are still listed separately. Star with a connected Strip.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_15d067cfd5a8','What makes a strip different from a blaze?','["A strip is more narrow","A strip is always on the muzzle only","A strip covers both eyes","A strip only appears on foals"]'::jsonb,'A strip is more narrow','markings','face-markings','easy',null,'Correct. A strip is the narrower marking; a blaze is wider.','The difference is width. Strip is narrow, blaze is wider.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_a08ef142b961','Which description best fits a star and strip?','["A forehead mark connected to a narrow line down the face","A muzzle patch only","A face with no white","A wide marking around both eyes"]'::jsonb,'A forehead mark connected to a narrow line down the face','markings','face-markings','easy',null,'Correct. Star and strip means a forehead star with a connected narrow line.','Star and strip combines a forehead marking with a narrow line down the face.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_6a9ee7bffb5b','Which marking is most centered on the muzzle?','["Snip","Star","Strip","Bald face"]'::jsonb,'Snip','markings','face-markings','easy',null,'Correct. A snip is a muzzle marking near the nostrils.','The muzzle marking near the nostrils is the snip.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_91e9099f398b','Which phrase describes an irregular marking?','["A marking with uneven or unusual edges","A marking only found on the legs","A marking that disappears in winter","A marking caused by tack"]'::jsonb,'A marking with uneven or unusual edges','markings','face-markings','easy',null,'Correct. Irregular markings have uneven shapes or edges that do not fit a tidy pattern.','Irregular refers to the shape or edges of the marking.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_949091442efe','What should you look at first when identifying a face marking?','["Where the white is located and how wide it is","The saddle color","The horse height","The mane length"]'::jsonb,'Where the white is located and how wide it is','markings','face-markings','easy',null,'Correct. Location and width are the biggest clues for face marking identification.','Start with where the white sits and how wide it is.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
