insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_bcb4cb148db0','True or false: A blaze usually runs down the front of the horse''s face.','["True","False"]'::jsonb,'True','markings','face-markings','easy',null,'Correct. A blaze runs down the front of the face.','Not quite. A blaze is a face marking that runs down the front of the face.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
