insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_d9820d8e4c3e','What is the best way to describe two separate white areas on the face?','["Name each visible marking","Call both areas a blaze","Ignore the smaller one","Use only the coat color"]'::jsonb,'Name each visible marking','markings','face-markings','easy',null,'Correct. Separate white areas should be named individually.','Separate markings are named separately so the description is clear.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_40602bbafc6b','Why can the same marking look slightly different from horse to horse?','["Markings vary in shape, size, and edges","All markings are identical","The name changes every season","Markings only show in bright sun"]'::jsonb,'Markings vary in shape, size, and edges','markings','face-markings','easy',null,'Correct. The same marking type can vary quite a bit in shape and size.','Markings are named by location and general shape, but individual horses vary.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_d34fbab791db','Which term is not a face marking?','["Sock","Star","Snip","Blaze"]'::jsonb,'Sock','markings','face-markings','easy',null,'Correct. A sock is a leg marking, not a face marking.','Star, snip, and blaze are face markings. Sock belongs to leg markings.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_e4e90e46668a','What does combination marking mean in this course?','["More than one marking term is used to describe what is seen","A horse has two coat colors","The horse has both front socks","The marking changes each month"]'::jsonb,'More than one marking term is used to describe what is seen','markings','face-markings','easy',null,'Correct. Combination markings use multiple terms, such as star and snip.','Combination means more than one face marking term is needed.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_9e0b48eade34','Which clue helps separate a blaze from a bald face?','["Whether the white expands around the eyes and cheeks","Whether the horse has a black mane","Whether the marking is on a hind leg","Whether the horse is tall"]'::jsonb,'Whether the white expands around the eyes and cheeks','markings','face-markings','easy',null,'Correct. A bald face is much wider and often reaches around the eyes and cheeks.','Compare how far the white spreads. A bald face covers much more of the face than a blaze.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_c2f7ba830409','What is the main clue used to name most leg markings?','["How high the white extends up the leg","The color of the mane","The horse height in hands","The shape of the ears"]'::jsonb,'How high the white extends up the leg','markings','leg-markings','easy',null,'Correct. Most leg marking names are based on the highest point reached by the white marking.','Not quite. For leg markings, start by looking at how high the white reaches from the hoof.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_22847d4f7e10','Which marking is a narrow band or area of white at the top of the hoof?','["Coronet","Sock","Stocking","Ermine mark"]'::jsonb,'Coronet','markings','leg-markings','easy',null,'Correct. A coronet marking sits at or just above the coronet band at the top of the hoof.','Look at the lowest white marking. A coronet marking is a narrow area at the top of the hoof.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_74a11b08ff7e','Which marking extends over the pastern but does not reach as high as a sock?','["Pastern","Stocking","Bald face","Star"]'::jsonb,'Pastern','markings','leg-markings','easy',null,'Correct. A pastern marking extends up over the pastern area.','The marking named for the pastern is the one that extends up over the pastern area.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_c08c9978db76','White that reaches to or around the fetlock joint is commonly called a:','["Fetlock marking","Snip","Blaze","Withers mark"]'::jsonb,'Fetlock marking','markings','leg-markings','easy',null,'Correct. A fetlock marking reaches the fetlock joint area.','Not quite. White that reaches the fetlock is described as a fetlock marking or ankle marking in many references.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_5ecaec003e05','A sock usually describes white that:','["Covers the fetlock and continues partway up the cannon","Only touches one heel","Stays only on the forehead","Runs down the nose"]'::jsonb,'Covers the fetlock and continues partway up the cannon','markings','leg-markings','easy',null,'Correct. A sock rises above the fetlock but does not extend all the way to the knee or hock.','A sock is a leg marking that covers the fetlock and rises partway up the cannon.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_bd5de1f96fa9','A stocking usually describes white that:','["Extends high up the leg toward the knee or hock","Only circles the top of the hoof","Appears only on the muzzle","Is a dark spot inside white"]'::jsonb,'Extends high up the leg toward the knee or hock','markings','leg-markings','easy',null,'Correct. A stocking is a high white leg marking extending toward the knee or hock.','The highest common white leg marking in this set is the stocking.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_c538e1f861c6','Which part of the horse is used as the upper joint reference on a front leg?','["Knee","Hock","Muzzle","Poll"]'::jsonb,'Knee','markings','leg-markings','easy',null,'Correct. The knee is the upper joint reference for the front leg.','Front legs use the knee as the upper joint reference.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_ff020abb305f','Which part of the horse is used as the upper joint reference on a hind leg?','["Hock","Knee","Forelock","Withers"]'::jsonb,'Hock','markings','leg-markings','easy',null,'Correct. The hock is the upper joint reference for the hind leg.','Hind legs use the hock as the upper joint reference.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
