insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_8eb708a6d2e0','A clear identification description should include:','["Which leg the marking is on","Only the horse’s barn name","The saddle color","Only the horse’s height"]'::jsonb,'Which leg the marking is on','markings','leg-markings','easy',null,'Correct. Include the leg: left front, right front, left hind, or right hind.','For identification, say which specific leg carries the marking.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
