insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_cfbcd66552a1','If white reaches the fetlock on only one part of the leg, the clearest description is:','["Partial fetlock","Full stocking","Bald face","Plain leg"]'::jsonb,'Partial fetlock','markings','leg-markings','easy',null,'Correct. Partial fetlock describes white that reaches the fetlock in an incomplete or uneven way.','Use partial when the white reaches that height on only part of the leg.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
