insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_e0b4251516b2','The muzzle is best described as:','["The soft lower face including the nostrils and lips","The area between the eyes","The lower jaw only","The bony ridge of the nose"]'::jsonb,'The soft lower face including the nostrils and lips','anatomy','parts-of-the-horse','easy',null,'Correct. The muzzle is the soft lower portion of the face — nostrils, upper lip, and lower lip.','The muzzle is the soft lower face, including the nostrils and lips.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_0250ef24aae0','What is the area where the underside of the jaw meets the top of the neck called?','["Throatlatch","Crest","Poll","Cheek"]'::jsonb,'Throatlatch','anatomy','parts-of-the-horse','easy',null,'Correct. The throatlatch is where the jaw meets the neck. A bridle strap of the same name passes through this region.','Where the jaw meets the neck is the throatlatch.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
