insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_d434d90dd77a','Where is a horse''s height measured from?','["The withers","The poll","The croup","The point of shoulder"]'::jsonb,'The withers','anatomy','parts-of-the-horse','easy',null,'Correct. Horse height is always measured at the withers — the highest point of the back between the shoulder blades.','Height is measured at the withers, not the head or any other point.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
