insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_c4d2b295e508','Which of the following is a neurological sign requiring immediate veterinary contact?','["Mild stiffness after a long stall rest","Incoordination, stumbling, or circling without obvious musculoskeletal cause","A horse that is reluctant to pick up one canter lead","Reduced appetite for one feeding"]'::jsonb,'Incoordination, stumbling, or circling without obvious musculoskeletal cause','health','equine-first-aid-basics','easy',null,'Correct.','Not quite. The correct answer is Incoordination, stumbling, or circling without obvious musculoskeletal cause.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_c4eb400c790d','A handler finds a horse in a stall with a severely swollen lower leg, standing with only the toe of that foot touching the ground. What is the appropriate response?','["Apply a cold hose and monitor for 24 hours","Walk the horse to evaluate the grade of lameness","Do not force the horse to walk — assess for signs of distress, take vital signs, and call the veterinarian","Wrap the leg tightly in a pressure bandage to reduce swelling"]'::jsonb,'Do not force the horse to walk — assess for signs of distress, take vital signs, and call the veterinarian','health','equine-first-aid-basics','easy',null,'Correct.','Not quite. The correct answer is Do not force the horse to walk — assess for signs of distress, take vital signs, and call the veterinarian.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_7d1e3d9c3e42','What is the normal temperature range for an adult horse at rest?','["99–101°F (37.2–38.3°C)","95–98°F (35–37°C)","102–104°F (38.9–40°C)","97–100°F (36.1–37.8°C)"]'::jsonb,'99–101°F (37.2–38.3°C)','health','equine-health-disease-prevention','medium',null,'Correct. Normal equine temperature is 99–101°F. Above 101°F may indicate fever; above 102°F is a veterinary concern.','Normal equine temperature is 99–101°F (37.2–38.3°C). Temperature should be taken rectally with the horse at rest.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_04d5495a39d1','What is the normal resting heart rate for an adult horse?','["28–44 beats per minute","60–80 beats per minute","15–25 beats per minute","50–70 beats per minute"]'::jsonb,'28–44 beats per minute','health','equine-health-disease-prevention','medium',null,'Correct. A resting heart rate of 28–44 bpm is normal for adult horses. An elevated rate at rest is a pain or distress signal.','Normal resting heart rate is 28–44 bpm. Rates above 50–60 bpm at rest suggest significant pain, illness, or distress.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_0aa1b50493d5','Normal capillary refill time in a horse is:','["Under 2 seconds","3–5 seconds","Under 5 seconds","Under 10 seconds"]'::jsonb,'Under 2 seconds','health','equine-health-disease-prevention','medium',null,'Correct. Press the gums firmly, release, and count. Pink color should return within 2 seconds. Longer times suggest circulatory compromise.','Capillary refill time should be under 2 seconds. Press the gum, release, and watch color return. Over 2 seconds is abnormal.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_2e80e0bd8efe','Normal gut sounds in a healthy horse should be present in:','["All four quadrants of the abdomen","The right side only","The upper left quadrant only","Gut sounds are not normally present in horses"]'::jsonb,'All four quadrants of the abdomen','health','equine-health-disease-prevention','medium',null,'Correct. Normal gut sounds — borborygmi — should be audible in all four quadrants with a stethoscope. Absent or reduced sounds indicate reduced gut motility.','Gut sounds should be present in all four quadrants. Absent or very reduced sounds indicate reduced gut motility, which is a sign of colic.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_f4e051b0a144','What is the primary distinction between preventive care and reactive care?','["Preventive care addresses health before problems develop; reactive care responds to problems after they appear","Preventive care costs more than reactive care","Preventive care is used only for horses in competition","Reactive care uses natural remedies; preventive care uses medications"]'::jsonb,'Preventive care addresses health before problems develop; reactive care responds to problems after they appear','health','equine-health-disease-prevention','medium',null,'Correct. Preventive care — vaccination, deworming, dental care, wellness exams — intercepts problems before they become costly or life-threatening. Reactive care responds to established disease.','Preventive care intercepts problems before they develop. Reactive care responds to problems that have already appeared. Preventive care is almost always less expensive and more effective.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_4fa25e4fd310','What is biosecurity in an equine facility?','["Practices that prevent the introduction and spread of infectious disease within a horse population","The process of testing horses for infectious diseases before sale","The vaccination schedule required for horses entering competition","Documentation required when horses cross state lines"]'::jsonb,'Practices that prevent the introduction and spread of infectious disease within a horse population','health','equine-health-disease-prevention','medium',null,'Correct. Biosecurity encompasses isolation of new arrivals, not sharing equipment between horses, monitoring for disease signs, and protocols for managing suspected cases.','Biosecurity is the set of practices that prevent disease from entering or spreading in a horse facility: isolation, dedicated equipment, monitoring, and movement restrictions.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_21c941302323','Why is documenting a horse''s health records important beyond regulatory requirements?','["Complete records enable pattern recognition, support veterinary decisions, and allow emergency care providers to understand the horse''s history","Health records are only required for horses in competition","Records are primarily for insurance purposes, not health management","The only required record is the annual Coggins test result"]'::jsonb,'Complete records enable pattern recognition, support veterinary decisions, and allow emergency care providers to understand the horse''s history','health','equine-health-disease-prevention','medium',null,'Correct. Health records reveal trends — changes in weight, vaccination gaps, deworming intervals — that a veterinarian can use to guide preventive care decisions and diagnose recurring problems.','Health records serve active management functions: they reveal patterns, support veterinary decision-making, and allow anyone caring for the horse in an emergency to understand its history.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_a0677fa2c01e','The annual wellness exam is most valuable because it:','["Establishes healthy baselines that make future deviations recognizable","Replaces the need for emergency veterinary calls","Provides documentation required by all boarding facilities","Is the only time vaccines can be administered safely"]'::jsonb,'Establishes healthy baselines that make future deviations recognizable','health','equine-health-disease-prevention','medium',null,'Correct. A heart rate of 38 bpm or a temperature of 100°F means something different when the examiner knows a horse''s normal is 32 bpm and 99.5°F. Baselines make deviations meaningful.','The wellness exam establishes baselines for that individual horse — weight, heart rate, temperature, dental status — so future deviations can be recognized quickly and interpreted accurately.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_ce5e5ad52ec4','What minimum isolation period is recommended for a new horse arriving at a facility?','["14–21 days","3–5 days","48–72 hours","One week exactly"]'::jsonb,'14–21 days','health','equine-health-disease-prevention','medium',null,'Correct. A 14–21 day isolation period covers the incubation period of most common equine infectious diseases, allowing any illness the horse is incubating to become apparent before contact with resident horses.','Minimum 14–21 days of isolation from resident horses. This covers the incubation period of most common equine infectious diseases and allows incubating illness to become apparent before herd contact.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_f854cbc14f20','Which member of the equine health team sets the deworming protocol and interprets fecal egg counts?','["The veterinarian","The farrier","The equine dentist","The barn manager"]'::jsonb,'The veterinarian','health','equine-health-disease-prevention','medium',null,'Correct. The veterinarian interprets diagnostic tests (fecal egg counts, blood work) and designs the deworming protocol. Other team members — farrier, dentist, barn manager — address their respective areas of expertise.','The veterinarian designs and oversees the deworming program, interprets fecal egg counts, and makes treatment decisions. The farrier maintains hoof health; the dentist addresses dental care.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_144cb498646d','Which vaccines are classified as AAEP core vaccines, recommended for all horses in North America?','["Tetanus, EEE/WEE, West Nile Virus, and Rabies","Strangles, Influenza, Herpesvirus, and Botulism","Potomac Horse Fever, Rotavirus, and Anthrax","All vaccines listed are core vaccines"]'::jsonb,'Tetanus, EEE/WEE, West Nile Virus, and Rabies','health','equine-health-disease-prevention','medium',null,'Correct. Tetanus, EEE/WEE, West Nile, and Rabies are the four AAEP core vaccines recommended annually for every horse in North America.','AAEP core vaccines: Tetanus, Eastern/Western Equine Encephalomyelitis, West Nile Virus, and Rabies. All four are recommended annually regardless of geography or use level.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_42ebe46ea468','EEE (Eastern Equine Encephalomyelitis) is notable for which statistic?','["A fatality rate of approximately 75–90% in affected horses","Being treatable with a single course of antibiotics","Causing only mild respiratory signs in most horses","Being transmitted by ticks, not mosquitoes"]'::jsonb,'A fatality rate of approximately 75–90% in affected horses','health','equine-health-disease-prevention','medium',null,'Correct. EEE is one of the most lethal vaccine-preventable diseases in horses. Most horses that develop clinical neurological signs do not survive, which is why annual vaccination before mosquito season is essential.','EEE carries a case fatality rate of approximately 75–90% in affected horses. It is a core vaccine because vaccination is essentially the only effective prevention — treatment after clinical signs are established has poor results.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_51975b743d7b','West Nile Virus arrived in North America in which year?','["1999","1987","2005","2012"]'::jsonb,'1999','health','equine-health-disease-prevention','medium',null,'Correct. West Nile Virus was introduced to North America through New York in 1999 and spread across the continent within four years, causing thousands of equine deaths before vaccination became widespread.','West Nile Virus arrived in North America in 1999 through New York City and spread rapidly across the continent within four years, causing significant equine mortality before vaccination was widely adopted.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_bce412e9cbe6','Tetanus in horses is caused by:','["Clostridium tetani bacteria found in soil and manure","A viral infection transmitted by mosquitoes","A fungal infection from contaminated hay","A nutritional deficiency in selenium or calcium"]'::jsonb,'Clostridium tetani bacteria found in soil and manure','health','equine-health-disease-prevention','medium',null,'Correct. Clostridium tetani is an anaerobic soil bacterium. It enters through wounds and produces a neurotoxin (tetanospasmin) that cannot be neutralized once it binds to neural tissue. Annual vaccination is essential.','Tetanus is caused by Clostridium tetani, an anaerobic bacterium ubiquitous in soil and manure. It enters through any wound. Horses are more susceptible than most domestic species.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_a4fb6176a153','When should an additional tetanus booster be administered beyond the annual vaccination?','["Within 24 hours of any significant wound, surgery, or foaling","Only if the horse has not been vaccinated in over 18 months","Tetanus does not require additional boosters beyond the annual schedule","Only after exposure to an infected horse"]'::jsonb,'Within 24 hours of any significant wound, surgery, or foaling','health','equine-health-disease-prevention','medium',null,'Correct. Any puncture, laceration, surgical incision, or foaling event creates a potential entry point for Clostridium tetani and triggers a booster recommendation within 24 hours, regardless of the annual vaccination schedule.','Tetanus requires a booster within 24 hours of significant wounds, surgical procedures, and foaling. The anaerobic environment of deep wounds is an ideal growth environment for Clostridium tetani.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_793894b4d347','Influenza and herpesvirus vaccines are classified as risk-based rather than core because:','["They provide shorter-lived immunity and are most valuable for horses with frequent exposure to other horses","They are not effective enough to be recommended for all horses","They are too expensive for routine use","They are only available by prescription and require veterinary administration"]'::jsonb,'They provide shorter-lived immunity and are most valuable for horses with frequent exposure to other horses','health','equine-health-disease-prevention','medium',null,'Correct. Risk-based vaccines address diseases where the risk varies significantly based on the horse''s use and exposure level. Horses that stay home with a closed herd have very different exposure risk than horses that travel to shows monthly.','Influenza and herpesvirus vaccines are risk-based because they provide shorter-lived immunity and their value depends heavily on exposure frequency. Every-6-month boosters are recommended for horses that travel or compete.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_f6836de936c3','What does a Coggins test detect, and what is the consequence of a positive result?','["Antibodies to Equine Infectious Anemia (EIA) — positive horses must be quarantined or euthanized","Intestinal parasite eggs — high counts require treatment","Equine influenza antibodies — positive horses must rest for 30 days","Blood glucose levels — elevated levels indicate metabolic disease"]'::jsonb,'Antibodies to Equine Infectious Anemia (EIA) — positive horses must be quarantined or euthanized','health','equine-health-disease-prevention','medium',null,'Correct. EIA is a reportable disease with no vaccine or cure. A negative Coggins test is required for interstate transport and most events. Positive horses face permanent quarantine or euthanasia under federal regulations.','The Coggins test detects antibodies to EIA (Equine Infectious Anemia). EIA has no vaccine or treatment — positive horses must be permanently quarantined or humanely euthanized per federal regulations.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_ac2fdb753528','West Nile Virus is transmitted to horses by:','["Mosquitoes that have fed on infected birds","Direct horse-to-horse contact","Contaminated water sources","Ticks in tall grass"]'::jsonb,'Mosquitoes that have fed on infected birds','health','equine-health-disease-prevention','medium',null,'Correct. West Nile Virus is an arbovirus — mosquitoes acquire it by feeding on infected wild birds and then transmit it to horses and humans. Horses are dead-end hosts and cannot spread the virus to other horses.','West Nile Virus is transmitted by mosquitoes that have fed on infected birds. Horses are dead-end hosts — they cannot spread the virus to other horses or to humans directly.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_c59b7fbec84e','What is the purpose of a fecal egg count (FEC) in a strategic deworming program?','["To identify which horses carry significant parasite burdens and need treatment","To determine the correct brand of dewormer for all horses","To detect tapeworm infections specifically","To replace annual vaccination with parasite testing"]'::jsonb,'To identify which horses carry significant parasite burdens and need treatment','health','equine-health-disease-prevention','medium',null,'Correct. FECs classify horses as low, moderate, or high shedders. Treating only high shedders concentrates drug use where it provides the most benefit and slows resistance development in the parasite population.','Fecal egg counting identifies horses with significant parasite burdens so treatment can be targeted to those animals — not applied indiscriminately to all horses on a fixed schedule.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_e47574d278a5','Anthelmintic resistance develops in parasite populations because:','["Blanket calendar deworming selects for resistant worms that survive treatment","Horses develop immunity to dewormers after repeated use","Wild horses introduce resistant strains into domestic herds","Dewormers lose potency after storage"]'::jsonb,'Blanket calendar deworming selects for resistant worms that survive treatment','health','equine-health-disease-prevention','medium',null,'Correct. When all horses are treated repeatedly regardless of actual need, worm populations that can survive the drug are selected to reproduce — rapidly increasing the proportion of resistant worms in the population.','Resistance develops through natural selection: treating all horses repeatedly selects for worms that can survive deworming, passing resistance to their offspring and eventually dominating the local parasite population.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_3ed347072de7','A fecal egg count reduction test (FECRT) is used to:','["Determine whether a specific dewormer is effective on a specific farm''s parasite population","Measure how many parasites are present before starting any deworming program","Identify which species of parasites are most common on a pasture","Test whether a horse has developed immunity to parasite infection"]'::jsonb,'Determine whether a specific dewormer is effective on a specific farm''s parasite population','health','equine-health-disease-prevention','medium',null,'Correct. The FECRT compares egg counts before and 14 days after treatment. A reduction below 95% indicates the parasites on that farm are resistant to the drug class used.','The FECRT tests whether a chosen anthelmintic is actually working on the parasite population of a specific farm. It is the only reliable method for detecting drug resistance in a particular horse population.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_f6298216d423','Which drug is the most reliable treatment for tapeworms in horses?','["Praziquantel","Ivermectin","Fenbendazole","Pyrantel at standard dose"]'::jsonb,'Praziquantel','health','equine-health-disease-prevention','medium',null,'Correct. Praziquantel is the most reliable tapeworm treatment. Double-dose pyrantel is an alternative. Standard-dose ivermectin and benzimidazoles are not reliably effective against tapeworms.','Praziquantel is the most reliable tapeworm treatment. Double-dose pyrantel is an alternative. Standard ivermectin dose does not cover tapeworms.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_62cc0916c202','Environmental management of parasite burden includes:','["Removing manure from pastures at least twice weekly to reduce infective larvae","Applying lime to all pastures monthly","Keeping horses in stalls full-time to eliminate pasture exposure","Rotating to a new pasture daily"]'::jsonb,'Removing manure from pastures at least twice weekly to reduce infective larvae','health','equine-health-disease-prevention','medium',null,'Correct. Infective strongyle larvae develop from eggs on pasture. Removing manure twice weekly significantly reduces the larval burden that horses ingest while grazing. Pasture rotation and avoiding overcrowding are also important.','Removing manure from pastures at least twice weekly interrupts the larval lifecycle. Composting kills most larvae. Overcrowding increases exposure — ideally at least 2 acres per horse is the standard.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_79753ad7ea3f','What percentage of a typical herd is responsible for the majority of parasite eggs shed on pasture?','["Approximately 20% of horses shed approximately 80% of the eggs","All horses shed equally","High shedders make up approximately 50% of any herd","Only horses with clinical signs shed significant parasite eggs"]'::jsonb,'Approximately 20% of horses shed approximately 80% of the eggs','health','equine-health-disease-prevention','medium',null,'Correct. Research consistently shows that a minority of horses carry and shed the majority of parasites. Strategic deworming focuses on these high shedders, reducing total drug use while addressing the major source of environmental contamination.','Approximately 20% of horses produce 80% of the egg burden in a herd. Treating only these high shedders reduces drug use significantly without compromising parasite control.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_f05e18693e04','A high shedder on fecal egg count testing has a result of:','["Greater than 500 eggs per gram","Less than 200 eggs per gram","200–500 eggs per gram","Any positive result is classified as high shedder"]'::jsonb,'Greater than 500 eggs per gram','health','equine-health-disease-prevention','medium',null,'Correct. High shedders: >500 eggs per gram (epg). Moderate: 200–500 epg. Low: <200 epg. High shedders are the priority for treatment and contribute the most to environmental contamination.','High shedder classification = >500 eggs per gram. Moderate = 200–500 epg. Low = <200 epg. High shedders require prompt treatment; low shedders require only periodic monitoring.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_be55a929a329','Early signs of colic include:','["Pawing, looking at the flank, elevated heart rate, and lack of gut sounds","Increased appetite, high energy level, and bright eye","Nasal discharge, elevated respiratory rate, and coughing","Swelling in all four limbs and digital pulse"]'::jsonb,'Pawing, looking at the flank, elevated heart rate, and lack of gut sounds','health','equine-health-disease-prevention','medium',null,'Correct. Pawing, flank-watching, elevated heart rate, and reduced or absent gut sounds are hallmark early colic signs. Rolling and repeated attempts to lie down and rise indicate more severe pain.','Early colic signs: pawing, looking at the flank, elevated heart rate, reduced or absent gut sounds, and reluctance to move. More severe colic produces persistent rolling, sweating, and elevated heart rate above 60 bpm.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_72cd23f45e49','Strangles is caused by:','["Streptococcus equi subsp. equi","Equine influenza virus","Clostridium tetani","Equine herpesvirus type 1"]'::jsonb,'Streptococcus equi subsp. equi','health','equine-health-disease-prevention','medium',null,'Correct. Strangles is a highly contagious bacterial infection caused by Streptococcus equi subsp. equi. It affects the upper respiratory tract and lymph nodes under the jaw and in the throatlatch area.','Strangles is caused by Streptococcus equi subsp. equi, a bacterium spread through direct contact and contaminated equipment, water sources, and surfaces.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_0e6fbe4589fd','What is required before a strangles outbreak is declared resolved and horses can move off the property?','["Two consecutive negative culture results (typically guttural pouch lavage, 14 days apart)","A single negative nasal swab","14 days after all visible abscesses have ruptured and drained","Clearance from a veterinarian after physical exam only"]'::jsonb,'Two consecutive negative culture results (typically guttural pouch lavage, 14 days apart)','health','equine-health-disease-prevention','medium',null,'Correct. Strangles carriers — horses that appear recovered but continue to shed bacteria from their guttural pouches — are a common source of re-infection and facility-wide spread. Two negative cultures at a 14-day interval confirm resolution.','Strangles requires two consecutive negative culture results (typically guttural pouch lavage, PCR or culture, 14 days apart) before the outbreak is declared resolved and horse movement can resume.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_6541278790bd','What is the primary reason why horses with equine influenza must be given extended rest after the fever resolves?','["The damaged respiratory epithelium is vulnerable to secondary bacterial infection, which can cause permanent lung damage","Influenza spreads most rapidly in the first 2 weeks after fever resolution","Horses returned to work early develop permanent exercise intolerance","The virus remains active in the lungs for up to 4 weeks after clinical signs resolve"]'::jsonb,'The damaged respiratory epithelium is vulnerable to secondary bacterial infection, which can cause permanent lung damage','health','equine-health-disease-prevention','medium',null,'Correct. Influenza virus damages the ciliated respiratory epithelium, removing the natural defense against bacterial colonization. Secondary bronchopneumonia during this vulnerable period can cause permanent airway damage and chronic respiratory problems.','The respiratory epithelium damaged by influenza is vulnerable to secondary bacterial bronchopneumonia during recovery. Returning to work before full healing creates conditions for serious secondary infection. Rest for at least 5–7 days after the last sign of fever is the standard guideline.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_d542cb1e7326','Equine Herpesvirus Myeloencephalopathy (EHM) most commonly occurs as a complication of:','["EHV-1 infection","EHV-4 infection","Equine influenza","Strangles infection"]'::jsonb,'EHV-1 infection','health','equine-health-disease-prevention','medium',null,'Correct. EHM is specifically associated with EHV-1 (not EHV-4). It results from EHV-1 replication within blood vessels supplying the spinal cord and brain, causing vasculitis and subsequent neurological signs.','EHM is a complication of EHV-1 infection. EHV-4 primarily causes respiratory disease. EHM involves EHV-1 replication in blood vessels supplying the nervous system, causing vasculitis and neurological signs.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_e6be7b386824','Early signs of laminitis include:','["Heat in the hooves, bounding digital pulse, and weight-shifted stance (leaning back to take weight off toes)","Nasal discharge, coughing, and elevated rectal temperature","Quidding, head tossing under saddle, and one-sided nasal discharge","Ataxia, hindlimb weakness, and urinary incontinence"]'::jsonb,'Heat in the hooves, bounding digital pulse, and weight-shifted stance (leaning back to take weight off toes)','health','equine-health-disease-prevention','medium',null,'Correct. These three signs — hoof heat, bounding digital pulse, and the characteristic backward-leaning stance — are the hallmarks of early laminitis. Veterinary and farriery intervention at this stage can prevent coffin bone rotation.','Early laminitis: heat in the hooves, bounding digital pulse at the back of the pastern, and the characteristic stance where the horse leans back on the hindlimbs to take weight off the toe area.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_08d21cff30ab','What is dental floating?','["Filing down the sharp enamel points on a horse''s cheek teeth to restore even grinding surfaces","Removing wolf teeth to improve bit contact","Polishing the incisors to assess wear patterns","A diagnostic procedure using dental radiographs"]'::jsonb,'Filing down the sharp enamel points on a horse''s cheek teeth to restore even grinding surfaces','health','equine-health-disease-prevention','medium',null,'Correct. Floating removes the sharp points that form on the outer edges of upper cheek teeth and inner edges of lower cheek teeth from uneven wear, preventing pain and restoring efficient grinding surfaces.','Dental floating files the sharp enamel points that develop on cheek teeth from normal wear, allowing comfortable and efficient chewing. It is recommended annually for horses over three years old.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_7e6a9b778d25','Quidding is defined as:','["Dropping partially chewed feed from the mouth — a primary sign of dental pain","Refusing to eat for more than 12 hours","Grinding the teeth audibly (bruxism)","Dribbling water during drinking"]'::jsonb,'Dropping partially chewed feed from the mouth — a primary sign of dental pain','health','equine-health-disease-prevention','medium',null,'Correct. Quidding occurs when a horse forms a feed bolus but cannot chew it without pain, dropping it before swallowing. It indicates sharp enamel points or other dental pathology causing pain during mastication.','Quidding = dropping partially chewed feed from the mouth. It is the most visible and specific sign of active dental pain. Horses that quid are at risk for weight loss and choke (esophageal obstruction).') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_244ec32b71d4','Why do horses require periodic dental floating throughout their lives?','["Uneven wear from normal chewing produces sharp enamel points on the cheek teeth that cause pain and reduce feed efficiency","Horses'' teeth are naturally smooth and become sharp only from eating hard feeds","Wolf teeth cause all major dental problems and their removal prevents future issues","Horse teeth do not naturally wear evenly because they are composed of soft dentine"]'::jsonb,'Uneven wear from normal chewing produces sharp enamel points on the cheek teeth that cause pain and reduce feed efficiency','health','equine-health-disease-prevention','medium',null,'Correct. The lateral chewing motion creates differential wear — sharp points form on the outer edges of upper cheek teeth and inner edges of lower cheek teeth. These points lacerate the cheeks and tongue, causing pain.','Normal chewing creates uneven wear, producing sharp enamel points on cheek tooth edges. These points lacerate soft tissue and cause pain during chewing — hence the need for annual filing (floating).') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_295eec9aa50a','What are wolf teeth in horses?','["Small first premolars (vestigial teeth) that can interfere with bit contact and are routinely removed","The canine teeth present in male horses","The deciduous teeth that must be removed at age 2","The molars at the very back of the dental arcade"]'::jsonb,'Small first premolars (vestigial teeth) that can interfere with bit contact and are routinely removed','health','equine-health-disease-prevention','medium',null,'Correct. Wolf teeth are small vestigial first premolars that sit just in front of the first cheek teeth. They can interfere with bit contact and cause pain — they are routinely removed when young horses begin training.','Wolf teeth are small vestigial first premolars. They can interfere with bit placement and cause discomfort during riding. Routine removal when the horse begins training is the standard management approach.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_cd695e2b6840','Horses have hypsodont teeth, which means:','["Their teeth have an extended crown that erupts continuously throughout life as grinding surfaces wear down","Their teeth stop erupting at maturity, as in most mammals","Their incisors are shorter than their molars","Their teeth cannot be filed without causing permanent damage"]'::jsonb,'Their teeth have an extended crown that erupts continuously throughout life as grinding surfaces wear down','health','equine-health-disease-prevention','medium',null,'Correct. Hypsodont teeth erupt continuously — this is what enables horses to grind forage efficiently across a long lifespan. However, the supply is finite, which is why very old horses eventually run out of usable tooth.','Hypsodont = high-crowned teeth that erupt continuously as the grinding surfaces wear down. This makes dental management a lifelong requirement, and explains why teeth eventually wear out in very old horses.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_7ed2d76c19e8','Annual dental examination is recommended to begin at age:','["Three years and older","Eight years and older","Dental exams are only needed when problems arise","Every five years for horses under fifteen"]'::jsonb,'Three years and older','health','equine-health-disease-prevention','medium',null,'Correct. Annual dental exams are recommended for all horses over three. Horses under three should be examined as deciduous teeth are replaced by permanent teeth — a period of significant dental change.','Annual dental exams are recommended starting at age three. Horses under three should be examined during the period of deciduous tooth shedding and permanent tooth eruption, which is an active and potentially uncomfortable phase.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_94d312ed1901','What indicates that a senior horse may need to transition away from standard hay?','["Significant tooth loss or severely worn teeth that prevent adequate chewing of long-stemmed forage","Any horse over twenty regardless of dental status","The horse preferring grain over hay as it ages","Weight gain from feed that is too calorie-dense"]'::jsonb,'Significant tooth loss or severely worn teeth that prevent adequate chewing of long-stemmed forage','health','equine-health-disease-prevention','medium',null,'Correct. As hypsodont teeth wear to the root, grinding efficiency declines. When a senior horse can no longer adequately process long-stemmed hay, alternatives such as soaked hay cubes, chopped forage, or complete feeds are needed to maintain body condition.','Senior horses with severely worn or missing teeth cannot adequately process long-stemmed hay. Soaked hay cubes, chopped forage, or complete senior feeds provide nutrition without requiring intact cheek teeth for grinding.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_615d37ece71a','A horse that consistently tilts its head to one side while chewing is most likely experiencing:','["Pain on the opposite side of the mouth, causing the horse to favor the less painful side","A training habit from early handling","Normal asymmetry in jaw muscle development","A neurological problem affecting the head and neck"]'::jsonb,'Pain on the opposite side of the mouth, causing the horse to favor the less painful side','health','equine-health-disease-prevention','medium',null,'Correct. Head tilting while chewing indicates the horse is avoiding pain — it chews on the comfortable side, which causes uneven dental wear over time and compounds the problem. This behavior warrants a dental examination.','Head tilting during chewing indicates the horse is avoiding the painful side — chewing exclusively on the more comfortable side. This behavioral compensation worsens over time as the avoided side develops increasingly uneven wear.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_9713bb612075','Dental work in horses requires sedation and a full-mouth speculum because:','["Without sedation and a speculum, the caudal (back) cheek teeth cannot be visualized or adequately treated","Horses object to any instrument near the face without sedation","Speculums replace the need for motorized floats","Sedation prevents the horse from swallowing dental instruments"]'::jsonb,'Without sedation and a speculum, the caudal (back) cheek teeth cannot be visualized or adequately treated','health','equine-health-disease-prevention','medium',null,'Correct. The back of the equine dental arcade is deep within the mouth and cannot be adequately visualized or worked on without both a full-mouth speculum to open the mouth and sedation to allow complete examination of all surfaces.','A full-mouth speculum and sedation are required for a complete equine dental exam. Without them, the caudal cheek teeth — where hooks, waves, and other pathology frequently develop — cannot be seen or treated.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_d1aa30d22441','What is the normal temperature range for a healthy adult horse at rest?','["99.5–101.5°F (37.5–38.6°C)","96–98°F (35.6–36.7°C)","102–104°F (38.9–40°C)","97–99°F (36.1–37.2°C)"]'::jsonb,'99.5–101.5°F (37.5–38.6°C)','health','vital-signs','medium',null,'Correct. The normal resting temperature for an adult horse is 99.5–101.5°F.','The normal resting temperature range is 99.5–101.5°F (37.5–38.6°C). Temperatures above or below this range warrant attention.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_937627161607','Where is a horse''s temperature taken?','["Rectally, using a digital thermometer","Under the foreleg, like in a human armpit","In the ear canal with a tympanic probe","On the skin surface of the neck"]'::jsonb,'Rectally, using a digital thermometer','health','vital-signs','medium',null,'Correct. Equine temperature is taken rectally with a digital thermometer for an accurate reading.','A horse''s temperature is taken rectally using a lubricated digital thermometer.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_bd496830ebf7','A horse''s temperature reads 103.4°F after standing quietly in the stall for several hours. How should this be interpreted?','["It is a fever and warrants veterinary attention","It is within the normal range for an active horse","It is slightly low and may indicate dehydration","It is normal for a horse on a warm day"]'::jsonb,'It is a fever and warrants veterinary attention','health','vital-signs','medium',null,'Correct. A temperature above 101.5°F is above normal. At 103.4°F, this horse has a clear fever and should be seen by a vet.','A temperature of 103.4°F is well above the normal ceiling of 101.5°F. This is a fever and requires veterinary evaluation.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_5d33f1e4fe2c','Why should a handler wait at least 30 minutes after exercise before taking a horse''s resting temperature?','["Exercise temporarily raises body temperature","Thermometers are less accurate when the horse is warm","The rectum is too contracted to insert a thermometer after work","Temperature only rises during illness, not exercise"]'::jsonb,'Exercise temporarily raises body temperature','health','vital-signs','medium',null,'Correct. Physical activity raises core temperature. Waiting 30 minutes after exercise provides a true resting measurement.','Exercise raises body temperature temporarily. Waiting 30 minutes allows the horse to return to its resting baseline before measuring.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_5266371b72a4','What should be done before inserting a rectal thermometer into a horse?','["Lubricate the tip with petroleum jelly or a water-based lubricant","Chill the thermometer in cold water first","Warm the thermometer in hot water to prevent discomfort","Shake the thermometer to reset the display"]'::jsonb,'Lubricate the tip with petroleum jelly or a water-based lubricant','health','vital-signs','medium',null,'Correct. Lubricating the tip makes insertion safer and more comfortable for the horse.','Always lubricate the thermometer tip before rectal insertion for the horse''s comfort and to allow safe placement.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_5fd97721471d','A subnormal temperature below 99°F in a resting adult horse may indicate:','["Shock, hypothermia, or serious systemic illness","The horse recently drank cold water","The thermometer was not inserted long enough","A normal variation in a very fit horse"]'::jsonb,'Shock, hypothermia, or serious systemic illness','health','vital-signs','medium',null,'Correct. A temperature below 99°F is not normal and may reflect a serious condition. Veterinary attention is needed.','A subnormal temperature below 99°F is a serious finding. It can indicate shock, hypothermia, or severe systemic illness.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_e87f4f8855ae','True or false: A horse''s temperature can be slightly elevated immediately after vigorous exercise in a healthy horse.','["True","False"]'::jsonb,'True','health','vital-signs','medium',null,'Correct. Exercise raises core temperature temporarily. This is normal and not a sign of illness if the horse recovers to a normal reading at rest.','This is true. A healthy horse''s temperature rises with exercise and returns to normal at rest. Always wait 30 minutes after activity for a reliable baseline.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_ad8ff08e514d','At what temperature is a fever generally considered to be present in a horse?','["Above 102°F (38.9°C)","Above 100°F (37.8°C)","Above 104°F (40°C)","Above 98°F (36.7°C)"]'::jsonb,'Above 102°F (38.9°C)','health','vital-signs','medium',null,'Correct. A temperature above 102°F is generally the clinical threshold for fever in horses.','A fever in horses is generally defined as a temperature above 102°F (38.9°C). The normal ceiling is 101.5°F.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_05bb357fe6db','What is the normal resting heart rate for an adult horse?','["28–44 beats per minute","10–20 beats per minute","60–80 beats per minute","50–70 beats per minute"]'::jsonb,'28–44 beats per minute','health','vital-signs','medium',null,'Correct. A healthy adult horse at rest has a heart rate between 28 and 44 beats per minute.','The normal resting heart rate for an adult horse is 28–44 beats per minute. Higher or lower rates at rest are worth investigating.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_bd3a98ba965a','Where can the facial artery be found to take a horse''s pulse?','["Along the underside of the lower jaw","On the top of the poll, between the ears","At the base of the tail","Behind the left knee"]'::jsonb,'Along the underside of the lower jaw','health','vital-signs','medium',null,'Correct. The facial artery runs along the inside of the lower jaw and is a reliable, accessible pulse point.','The facial artery is located along the underside of the lower jaw (mandible). It is one of the most commonly used pulse points.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_daecb7df990b','A handler counts 9 beats in 15 seconds. What is the horse''s heart rate per minute?','["36 bpm","18 bpm","54 bpm","45 bpm"]'::jsonb,'36 bpm','health','vital-signs','medium',null,'Correct. 9 beats × 4 = 36 beats per minute, which is within the normal range.','To convert: beats in 15 seconds × 4 = beats per minute. 9 × 4 = 36 bpm, which is within the normal range of 28–44 bpm.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_fe85f45cc9cf','A resting adult horse has a heart rate of 72 bpm. This reading is:','["Significantly elevated and warrants veterinary attention","At the high end of the normal range","Normal for a horse that has eaten recently","Normal for horses over 15 years old"]'::jsonb,'Significantly elevated and warrants veterinary attention','health','vital-signs','medium',null,'Correct. 72 bpm is nearly double the upper end of the normal resting range. This level of elevation at rest is a serious finding.','A resting heart rate of 72 bpm is far above the normal ceiling of 44 bpm. This requires veterinary evaluation — it often signals pain or illness.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_0ad3bde5ab86','True or false: Foals have higher resting heart rates than adult horses.','["True","False"]'::jsonb,'True','health','vital-signs','medium',null,'Correct. Newborn foals can have heart rates of 80–120 bpm, which gradually decrease over the first months of life.','This is true. Foals are born with much higher heart rates than adults — sometimes 80–120 bpm — which slow as they mature.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_410c8f2f9e4e','Where is the stethoscope placed to listen to a horse''s heartbeat?','["Just behind the left elbow on the chest wall","On the right side of the neck","On the horse''s lower belly near the flank","On the forehead between the eyes"]'::jsonb,'Just behind the left elbow on the chest wall','health','vital-signs','medium',null,'Correct. Placing the stethoscope just behind the left elbow gives the clearest access to heart sounds.','The stethoscope is placed just behind the left elbow on the chest wall to hear the heartbeat clearly.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_aec75055d238','A consistently low resting heart rate below 24 bpm in an adult horse should be:','["Reported to a veterinarian","Considered normal in a very fit horse","Ignored unless other symptoms appear","Confirmed by watching the nostril movement"]'::jsonb,'Reported to a veterinarian','health','vital-signs','medium',null,'Correct. While fit horses often have lower resting heart rates, a consistent rate below 24 bpm may indicate a cardiac irregularity.','A resting heart rate below 24 bpm is below the normal floor and should be reported to a vet, even if the horse appears otherwise healthy.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_8b0314b9c61a','Which of the following can temporarily raise a horse''s heart rate at rest?','["Pain, fear, or excitement","Drinking large amounts of water","Being in a cooler environment","Eating hay slowly"]'::jsonb,'Pain, fear, or excitement','health','vital-signs','medium',null,'Correct. Pain, fear, and excitement are all common non-illness causes of a temporarily elevated heart rate.','Pain, fear, and excitement all raise heart rate. Always assess the horse''s environment and demeanor when interpreting an elevated reading.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_3fcd6bfbc428','What is the normal respiratory rate for a resting adult horse?','["8–16 breaths per minute","20–30 breaths per minute","2–6 breaths per minute","18–25 breaths per minute"]'::jsonb,'8–16 breaths per minute','health','vital-signs','medium',null,'Correct. A resting adult horse typically breathes 8–16 times per minute.','The normal resting respiratory rate is 8–16 breaths per minute. Rates above or below this at rest are worth monitoring.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_11a337676663','How is respiratory rate counted by observing the horse?','["Count each rise and fall of the flank as one breath","Count each flare of one nostril as one breath","Count both nostrils separately and average them","Count the number of times the tail raises per minute"]'::jsonb,'Count each rise and fall of the flank as one breath','health','vital-signs','medium',null,'Correct. One complete breath = one rise and one fall of the flank. Count for 30 seconds and multiply by two.','Respiratory rate is counted by watching the flank. Each full rise and fall = one breath. Count for 30 seconds × 2 for breaths per minute.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_fb41c902a8b7','A resting horse is breathing 22 times per minute. This rate is:','["Above normal and worth investigating","Within the normal resting range","Below normal and worth investigating","Normal only during warm weather"]'::jsonb,'Above normal and worth investigating','health','vital-signs','medium',null,'Correct. 22 breaths per minute is above the normal ceiling of 16 at rest. The cause should be identified.','The normal resting ceiling is 16 breaths per minute. At 22, this horse is breathing faster than expected and should be assessed.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_467457a830db','In cold weather, what is a useful alternative to watching the flank when counting respiratory rate?','["Watch for visible puffs of air from the nostrils","Listen for breath sounds with a stethoscope on the chest","Count how often the horse blinks","Watch for movement of the mane or tail"]'::jsonb,'Watch for visible puffs of air from the nostrils','health','vital-signs','medium',null,'Correct. In cold conditions, each breath produces a puff of condensation from the nostrils that is easy to count.','When the flank is hard to see in cold weather, visible puffs of air from the nostrils are a reliable alternative to count breaths.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_c45c71e370a9','True or false: One breath equals one rise of the flank, not a full rise and fall.','["False","True"]'::jsonb,'False','health','vital-signs','medium',null,'Correct — this is false. One full breath = one rise AND one fall. Counting only rises would double the actual rate.','This is false. One breath equals both a rise AND a fall of the flank. Counting only the rise would give a doubled, inaccurate reading.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_7062351ca672','Labored or noisy breathing in a resting horse suggests:','["A respiratory problem that needs veterinary evaluation","The horse has been eating too quickly","Normal variation in breathing pattern","The horse is about to whinny"]'::jsonb,'A respiratory problem that needs veterinary evaluation','health','vital-signs','medium',null,'Correct. Labored or noisy breathing at rest is not normal and needs to be evaluated by a veterinarian.','Noisy or labored breathing at rest is a clear sign of a respiratory concern. Contact a veterinarian.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_6b96b082e49c','How many quadrants of the abdomen should be listened to when checking gut sounds?','["Four — upper and lower on each side","One — the left lower flank only","Two — one per side","Six — three per side"]'::jsonb,'Four — upper and lower on each side','health','vital-signs','medium',null,'Correct. The four quadrants are upper left, lower left, upper right, and lower right.','Gut sounds should be checked in four quadrants: upper left, lower left, upper right, and lower right. All four should have sounds.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_2029661b9186','What tool is used to listen to a horse''s gut sounds?','["A stethoscope","A digital thermometer","A blood pressure cuff","A penlight"]'::jsonb,'A stethoscope','health','vital-signs','medium',null,'Correct. A stethoscope is pressed against the abdomen wall to amplify the sounds the gut produces.','A stethoscope is the correct tool for checking gut sounds. It amplifies the gurgling and rumbling sounds produced by the digestive tract.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_4b5db763dd83','How long should a handler listen to each quadrant before deciding that gut sounds are absent?','["At least 60 seconds","At least 5 seconds","At least 10 seconds","At least 30 seconds"]'::jsonb,'At least 60 seconds','health','vital-signs','medium',null,'Correct. Gut sounds can be intermittent. Listening for at least 60 seconds provides a reliable assessment of each quadrant.','Listen for at least 60 seconds per quadrant before concluding sounds are absent. Gut sounds can be intermittent.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_161d64e963bf','What do normal gut sounds sound like?','["Gurgling, bubbling, or rumbling","A steady clicking or tapping","Complete silence in all quadrants","A high-pitched whistle on inhalation"]'::jsonb,'Gurgling, bubbling, or rumbling','health','vital-signs','medium',null,'Correct. A healthy gut produces gurgling, bubbling, or rumbling sounds as food and gas move through the digestive tract.','Normal gut sounds are described as gurgling, bubbling, or rumbling — sounds of a functioning digestive tract.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_2296b9567ed9','Complete silence in all four quadrants when checking gut sounds is:','["A significant concern that warrants calling a vet","Normal for a horse that has just been fed","Expected after a long ride","Normal in horses over 20 years old"]'::jsonb,'A significant concern that warrants calling a vet','health','vital-signs','medium',null,'Correct. Absent gut sounds in all quadrants indicate the digestive tract has slowed or stopped moving — a serious sign, often related to colic.','Absent gut sounds in all quadrants are always a concern. This indicates the gut may not be moving properly and a vet should be called.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_0bf8c87fbb10','Very loud, rushing gut sounds in a horse at rest may indicate:','["Increased gut motility, possibly associated with diarrhea or spasmodic colic","A perfectly normal, healthy digestive system","The horse is ready to be fed","Impaction colic"]'::jsonb,'Increased gut motility, possibly associated with diarrhea or spasmodic colic','health','vital-signs','medium',null,'Correct. Excessively loud, rapid gut sounds can indicate hypermotility — the gut moving faster than normal — which can accompany diarrhea or early colic.','Very loud, rushing sounds suggest the gut is moving faster than normal (hypermotility), which can occur with spasmodic colic or diarrhea.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_a2cbc32b70e2','True or false: Gut sounds should be present on both sides of the horse''s abdomen.','["True","False"]'::jsonb,'True','health','vital-signs','medium',null,'Correct. Sounds should be present in all four quadrants — two on the left and two on the right.','This is true. Sounds should be present in all four quadrants, both sides, upper and lower.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_149906515c5c','What does the skin tenting test assess?','["Hydration status","Body temperature","Heart rate","Respiratory health"]'::jsonb,'Hydration status','health','vital-signs','medium',null,'Correct. The skin tenting test measures how hydrated a horse is by testing skin elasticity.','The skin tenting test is a hydration check. How quickly skin returns to flat reflects the horse''s water and electrolyte balance.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_45a789fdfce3','How is the skin tenting test performed?','["Pinch a fold of skin on the neck or shoulder, release, and time how quickly it returns flat","Press the gum with a thumb and count refill time","Take a blood sample and send it to a lab","Watch how quickly the horse drinks a bucket of water"]'::jsonb,'Pinch a fold of skin on the neck or shoulder, release, and time how quickly it returns flat','health','vital-signs','medium',null,'Correct. The test involves pinching skin, releasing, and timing the return. Faster is better.','The skin tenting test involves pinching skin on the neck or shoulder, releasing, and counting how long it takes to return flat.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_01de98912703','In a well-hydrated horse, the skin should return to flat within:','["1–2 seconds","5–10 seconds","10–15 seconds","3–4 seconds"]'::jsonb,'1–2 seconds','health','vital-signs','medium',null,'Correct. A normal skin tenting test resolves within 1–2 seconds in a horse with good hydration.','Normal skin tenting resolves within 1–2 seconds. Slower return indicates dehydration.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_0492e23b39d6','The skin stays tented for 5 seconds before returning flat. What does this indicate?','["Moderate to severe dehydration","The horse is well hydrated","Normal variation in skin elasticity","The test was performed incorrectly"]'::jsonb,'Moderate to severe dehydration','health','vital-signs','medium',null,'Correct. A tent lasting 5 seconds indicates significant dehydration. Veterinary care may be needed.','A 5-second skin tent indicates moderate to severe dehydration. Normal is 1–2 seconds. At this level, contact a veterinarian.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_46ebd8034f08','True or false: The skin tenting test can be slightly less reliable in older horses due to reduced skin elasticity.','["True","False"]'::jsonb,'True','health','vital-signs','medium',null,'Correct. Older horses may show a slower skin return even when adequately hydrated. Always use the test as one piece of a broader assessment.','This is true. Older horses naturally lose some skin elasticity, so their results may be slightly slower even when hydrated. Use the test alongside other vital signs.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_f358e15a1506','Where on the horse''s body is the skin tenting test most commonly performed?','["Neck or shoulder","Lower leg","Belly","Forehead"]'::jsonb,'Neck or shoulder','health','vital-signs','medium',null,'Correct. The neck and shoulder are the most common locations because the skin is loose enough to pinch easily.','The neck or shoulder are the standard locations for the skin tenting test — areas where the skin is loose and easy to pinch.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_e3c0d82251c7','Why should the skin tenting test be used alongside other vital signs rather than on its own?','["Some horses can appear to have normal skin tenting even with mild dehydration","The test only works on horses under 10 years old","The test is only valid in cold weather","Skin tenting results are always inaccurate"]'::jsonb,'Some horses can appear to have normal skin tenting even with mild dehydration','health','vital-signs','medium',null,'Correct. The skin tenting test gives useful information, but it has limitations. Other vital signs help build a fuller picture.','The skin tenting test is a helpful tool but not foolproof — some horses may not show obvious tenting even with early dehydration. Always assess multiple vital signs together.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_73842ccfac66','What color should a healthy horse''s gums be?','["Pink (salmon pink)","Bright red","Pale white","Yellow"]'::jsonb,'Pink (salmon pink)','health','vital-signs','medium',null,'Correct. Healthy mucous membranes are salmon pink in color — moist and slippery to the touch.','Healthy gums should be pink (salmon pink) in color, moist, and slippery. Any other color is worth noting and possibly reporting.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_1d687c39b895','What does CRT stand for?','["Capillary Refill Time","Core Resting Temperature","Cardiac Rate Test","Circulation Response Timing"]'::jsonb,'Capillary Refill Time','health','vital-signs','medium',null,'Correct. CRT stands for Capillary Refill Time — the time it takes for blood to return to the gum after pressure is released.','CRT stands for Capillary Refill Time — the time it takes the gum to return to pink color after pressure is released.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_f60857bde62c','How is the capillary refill time test performed?','["Press a thumb on the upper gum for two seconds, release, and count until pink color returns","Pinch the skin on the neck and time the return","Listen to the chest with a stethoscope for 15 seconds","Insert a thermometer and read the display"]'::jsonb,'Press a thumb on the upper gum for two seconds, release, and count until pink color returns','health','vital-signs','medium',null,'Correct. Press firmly on the upper gum to blanch it, release, and count the seconds until color fully returns.','CRT is tested by pressing on the upper gum for two seconds, releasing, and timing how long it takes for the pink color to return.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_c9a59c022dbf','A normal capillary refill time in a healthy horse is:','["1–2 seconds","4–5 seconds","Under 5 minutes","3–4 seconds"]'::jsonb,'1–2 seconds','health','vital-signs','medium',null,'Correct. A healthy horse''s capillary refill time should be under 2 seconds.','Normal CRT is 1–2 seconds. Longer than 2 seconds indicates potential circulatory compromise and should be reported to a vet.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_51ab4b51f285','What is equine ethology?','["The scientific study of horse behavior in natural conditions","The study of horse nutrition and feed management","The practice of training horses for competition","Veterinary medicine focused on equine infectious disease"]'::jsonb,'The scientific study of horse behavior in natural conditions','behavior','horse-behavior-communication','medium',null,'Correct. Ethology is the scientific study of animal behavior in natural conditions — equine ethology applies that framework specifically to horses.','Ethology is the scientific study of animal behavior in natural conditions. Equine ethology examines what drives horse behavior in natural social and environmental contexts.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_deda7b39a5dc','Which of the following is one of the five natural behavioral response tendencies in horses?','["Fidget","Follow","Forage","Focus"]'::jsonb,'Fidget','behavior','horse-behavior-communication','medium',null,'Correct. The five natural responses are flee, fight, freeze, fidget, and friend. Fidget refers to displacement behaviors that appear under stress.','The five natural behavioral responses are flee, fight, freeze, fidget, and friend. Fidget refers to displacement behaviors such as weaving or cribbing that appear under stress or conflict.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_5b8df323ba9a','A horse that has been domesticated still retains its instinctive behavioral programming because:','["Domestication changes the environment but not the inherited behavioral wiring","Domestic horses are selectively bred to eliminate instincts","Instincts disappear within a few generations of captivity","Training replaces instinct entirely over time"]'::jsonb,'Domestication changes the environment but not the inherited behavioral wiring','behavior','horse-behavior-communication','medium',null,'Correct. Domestication changes the horse''s environment, but the underlying behavioral programming evolved over millions of years and cannot be removed by a few thousand years of human management.','Domestication changes the environments horses live in but does not remove the behavioral programming that evolved over millions of years. A stalled horse still carries the same instincts as a feral one.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_f1b889fede0a','The ethological reframe that changes how behavioral problems are approached is:','["Behavior is a predictable response to an identifiable trigger, not a personality fault","Horses behave badly because of insufficient training","All horse behavior is learned and therefore fully controllable","Instinctive behaviors can be trained away permanently"]'::jsonb,'Behavior is a predictable response to an identifiable trigger, not a personality fault','behavior','horse-behavior-communication','medium',null,'Correct. Ethology reframes problem behavior as predictable and trigger-based, which shifts management from blame to diagnosis.','The key ethological reframe is that behavior is a predictable response to an identifiable trigger — not a character flaw in the horse. This shift makes training and management more effective.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_f7016b146c7f','Which of the five natural responses is most likely operating when a horse weaves in its stall?','["Fidget","Freeze","Fight","Flee"]'::jsonb,'Fidget','behavior','horse-behavior-communication','medium',null,'Correct. Weaving is a stereotypy — a displacement behavior that falls under the ''fidget'' response category. It is a repetitive coping behavior that develops under chronic stress.','Weaving is a stereotypy — a repetitive displacement behavior. Displacement behaviors fall under the ''fidget'' response, which appears when the horse cannot use its primary response (flee) to resolve the stressor.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_63ad5367c8bf','Instinctive behaviors in horses differ from learned behaviors in that instinctive behaviors:','["Are present from birth and do not require prior experience","Are faster to learn but slower to extinguish","Must be conditioned through repetition","Only appear in wild horses, not domestic ones"]'::jsonb,'Are present from birth and do not require prior experience','behavior','horse-behavior-communication','medium',null,'Correct. Instinctive behaviors — flight response, herd-seeking, mutual grooming — are hardwired and present from birth without requiring any prior learning.','Instinctive behaviors are present from birth and do not require learning through experience. Learned behaviors develop through association and consequence — they can modify how instincts are expressed but cannot remove them.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_f200a1d2dc64','What does the flight zone represent?','["The perimeter within which a horse feels threatened and will move away","The maximum distance a horse can run at speed","The area around a water source a horse defends","The zone around the arena used for free longing"]'::jsonb,'The perimeter within which a horse feels threatened and will move away','behavior','horse-behavior-communication','medium',null,'Correct. The flight zone is the personal space perimeter — entering it applies spatial pressure that causes the horse to move away from the handler or object.','The flight zone is the perimeter around a horse within which it feels threatened and will move away. Handlers use it to direct horse movement through spatial pressure without physical contact.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_9bc5e6c0ce12','When a horse freezes in response to a perceived threat, it is most likely using which natural response?','["Freeze","Fidget","Friend","Fight"]'::jsonb,'Freeze','behavior','horse-behavior-communication','medium',null,'Correct. Freeze is a predator-evasion tactic — immobility reduces visual detection. It is most common in horses that cannot flee (confined space, tethered) and are not yet escalating to fight.','Freeze is immobility as a predator-evasion tactic. A horse that cannot flee will often freeze — holding still to avoid detection — before escalating to fight responses.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_379ee6ad4165','The ''friend'' response in the five natural behaviors refers to:','["Social bonding behaviors including mutual grooming and proximity-seeking","A learned behavior in which horses bond with a specific human handler","A trained response where the horse follows the handler on a loose lead","The process by which horses establish friendship hierarchies"]'::jsonb,'Social bonding behaviors including mutual grooming and proximity-seeking','behavior','horse-behavior-communication','medium',null,'Correct. ''Friend'' encompasses the full range of equine social bonding behaviors — mutual grooming, affiliative proximity, herd cohesion — that evolved alongside the social group structure of wild horses.','The ''friend'' response encompasses social bonding behaviors: mutual grooming, affiliative proximity, and herd cohesion. These behaviors evolved alongside the social group structure that is central to equine survival.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_964289c6b421','Understanding ethology helps handlers because:','["It provides a principled framework for diagnosing why a horse responds a certain way","It teaches specific training techniques that replace older horsemanship methods","It eliminates the need for veterinary consultation on behavioral problems","It provides breed-specific management guidelines"]'::jsonb,'It provides a principled framework for diagnosing why a horse responds a certain way','behavior','horse-behavior-communication','medium',null,'Correct. Ethological knowledge provides the diagnostic framework — the ''why'' behind behavior — which makes both training and management more effective and more humane.','Ethology provides the diagnostic framework for understanding why horses behave as they do. That ''why'' transforms problem-solving from reactive to principled.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_fec3320c4903','In a wild horse band, the lead mare primarily:','["Controls daily movement, routes, and grazing decisions","Protects the herd from predators at the perimeter","Determines breeding access for the stallion","Manages discipline of young horses in the group"]'::jsonb,'Controls daily movement, routes, and grazing decisions','behavior','horse-behavior-communication','medium',null,'Correct. The lead mare is the primary decision-maker for daily herd movement — where to go, when to move, and where to graze. Her role is often more influential than the stallion''s.','The lead mare controls day-to-day herd movement: routes, grazing timing, and responses to environmental changes. Her role is typically more influential than the stallion''s in daily herd management.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_b0625694d113','Herd hierarchy in domestic horses primarily determines:','["Priority access to food, water, and space","Who the lead handler must bond with first","Which horses are eligible for competition","When horses receive veterinary care"]'::jsonb,'Priority access to food, water, and space','behavior','horse-behavior-communication','medium',null,'Correct. Hierarchy in horse herds is resource-based — it determines who has priority access to food, water, shelter, and space. Higher-ranking horses can displace lower-ranking ones with minimal physical contact.','Herd hierarchy determines priority access to resources: food, water, shelter, and space. Higher-ranking horses can displace lower-ranking ones with signals as subtle as a pinned ear.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_e634e852044d','When a new horse is introduced into an established herd, the handler should expect:','["Hierarchy renegotiation with some conflict during the first few days","No behavioral change if the new horse is well-trained","The new horse to immediately establish dominance","The existing horses to leave the introduction area"]'::jsonb,'Hierarchy renegotiation with some conflict during the first few days','behavior','horse-behavior-communication','medium',null,'Correct. Any new horse introduction disrupts the existing hierarchy and requires renegotiation. Conflict is expected and is reduced by introducing horses over a fence before shared space.','A new horse always disrupts an established hierarchy. Conflict during the first few days is expected as ranking relationships are renegotiated. Introduction over a fence first reduces injury risk.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_a51198d798eb','Mutual grooming between horses has been documented to:','["Lower the heart rate of both horses involved","Establish temporary dominance without aggression","Indicate that both horses are equally ranked","Communicate alertness to environmental threats"]'::jsonb,'Lower the heart rate of both horses involved','behavior','horse-behavior-communication','medium',null,'Correct. Research has documented that heart rate decreases in both horses during mutual grooming, confirming its physiological calming function as well as its social bonding role.','Research has documented that heart rate decreases in both horses during mutual grooming — it has a measurable physiological calming effect, not only a social bonding function.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_2f85557df51b','A horse that becomes extremely anxious when separated from one companion is demonstrating:','["Herd instinct at an intensity that creates management problems","Aggressive dominance over the companion","Learned helplessness from insufficient training","Classical conditioning to the companion''s voice"]'::jsonb,'Herd instinct at an intensity that creates management problems','behavior','horse-behavior-communication','medium',null,'Correct. ''Buddy sour'' behavior is a normal herd bonding instinct operating at a problematic intensity. It is not stubbornness or dominance — it is a prey animal''s attachment to its perceived safety system.','Buddy sour behavior is herd bonding instinct at problematic intensity. The horse is not being stubborn — it is a prey animal responding to the loss of its perceived social safety. Systematic desensitization to separation addresses the underlying anxiety.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_19e5f89e90d6','Why do horses placed in solo housing often develop behaviors such as weaving, stall walking, or calling?','["These are expressions of social deprivation, not individual personality traits","The horses have been improperly trained for solo management","These behaviors indicate the horse is not suited for domestic management","The behaviors are signs of neurological conditions requiring treatment"]'::jsonb,'These are expressions of social deprivation, not individual personality traits','behavior','horse-behavior-communication','medium',null,'Correct. Weaving, stall walking, and repetitive calling in horses kept in isolation are typically expressions of social deprivation — a mismatch between the horse''s need for social contact and its management environment.','Repetitive behaviors in isolated horses are typically expressions of social deprivation, not individual character. Management changes that provide visual or physical contact with other horses often resolve these behaviors without additional training.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_ac770ea961df','When is herd conflict most likely to occur?','["During initial hierarchy formation and when new horses are introduced","When the dominant horse is removed for veterinary care","At feeding time regardless of the existing hierarchy","During extreme weather when horses compete for shelter"]'::jsonb,'During initial hierarchy formation and when new horses are introduced','behavior','horse-behavior-communication','medium',null,'Correct. Herd hierarchy, once established, is generally stable. Most conflict occurs when the hierarchy is initially formed or when a new horse enters the group and disrupts the existing ranking structure.','Established hierarchies are generally stable. The most common occasions for conflict are during initial hierarchy formation and when a new horse is introduced, requiring renegotiation of all existing rankings.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_27d82e84ad17','The stallion''s primary roles in a wild horse band are:','["Breeding and peripheral protection","Navigation and daily movement decisions","Resource allocation and discipline","Conflict resolution within the band"]'::jsonb,'Breeding and peripheral protection','behavior','horse-behavior-communication','medium',null,'Correct. In wild horse bands, the stallion''s primary roles are breeding and protection at the herd''s perimeter. The lead mare, not the stallion, handles daily movement and decision-making.','The stallion''s primary roles in a wild band are breeding and perimeter protection. Day-to-day movement and decision-making are the lead mare''s domain.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_fb58e9aa5e82','Which behavioral signal typically appears earliest in a horse''s stress escalation sequence?','["Muzzle tension","Ear pinning","Eye white showing","Tail clamping"]'::jsonb,'Muzzle tension','behavior','horse-behavior-communication','medium',null,'Correct. Muzzle tension — taut muscles around the mouth and jaw, pressed lips — often appears before the more obvious signals of ear position and eye white, making it a valuable early indicator.','Muzzle tension (tight lips, taut jaw muscles, wrinkled nostrils) typically appears before ear pinning or visible eye white — making the muzzle a more valuable early warning signal than these more obvious indicators.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_c48f515e18c7','Bruxism (teeth grinding) in a horse during work most likely indicates:','["Stress or discomfort with the current training situation","A learned behavior reinforced by previous owners","Normal processing behavior when a horse concentrates","A dental condition requiring immediate attention"]'::jsonb,'Stress or discomfort with the current training situation','behavior','horse-behavior-communication','medium',null,'Correct. Bruxism during work is a consistent indicator of stress or discomfort — either with pain, training pressure, bit contact, or the session''s demands. It is not a random habit.','Bruxism (teeth grinding) during work is a consistent behavioral signal of stress or discomfort. Intermittent teeth grinding that was not previously present warrants evaluation of bit fit, dental condition, and training approach.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_1a3720e3f680','A horse that inverts its back (raises head, drops and stiffens the back) when a rider sits is most likely:','["Protecting something — pain, fear, or anticipation of discomfort","Being dominant over the rider","Improperly trained to accept weight","Responding to distractions in the environment"]'::jsonb,'Protecting something — pain, fear, or anticipation of discomfort','behavior','horse-behavior-communication','medium',null,'Correct. Back inversion is a protective response — the horse is bracing against something. Pain (saddle fit, musculoskeletal), fear, or anticipation of discomfort from prior experience are the most common causes.','Back inversion is a protective bracing response, not a discipline problem. Pain, fear, or anticipation of discomfort are the most common causes. Saddle fit evaluation and veterinary assessment should precede any training response.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_09188caf7665','A tail clamped tightly to the hindquarters while a horse is being worked typically indicates:','["Fear or pain","Excitement and high energy","A desire to move forward","Relaxation in the current situation"]'::jsonb,'Fear or pain','behavior','horse-behavior-communication','medium',null,'Correct. A clamped tail is a protective signal — the horse is drawing inward. It is most commonly associated with fear, pain, or significant discomfort in the current situation.','A clamped tail — held tight against the hindquarters rather than swinging freely — indicates fear or pain. It is a protective signal, not an expression of energy or willingness.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_76d64387bfc2','Licking and chewing in a horse after the release of training pressure indicates:','["A shift from sympathetic to parasympathetic nervous system activity","That the horse understood and approved the training cue","A sign of hunger or anticipation of food","Continued stress from the training session"]'::jsonb,'A shift from sympathetic to parasympathetic nervous system activity','behavior','horse-behavior-communication','medium',null,'Correct. Licking and chewing at the moment of release is associated with a physiological shift from arousal (fight-or-flight) to rest — confirming the release was timed to genuine reduction in the horse''s stress level.','Licking and chewing at release is associated with a shift from sympathetic (fight-or-flight) to parasympathetic (rest-and-digest) activity. It confirms the release was timed to a genuine reduction in the horse''s arousal, not just an external pause.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_4c2915618da6','A horse that swishes its tail sharply and repeatedly while being ridden under leg pressure is communicating:','["Irritation or discomfort with the stimulus being applied","Enthusiasm and willingness to move forward","A request for more consistent leg aids","Fly irritation unrelated to the riding context"]'::jsonb,'Irritation or discomfort with the stimulus being applied','behavior','horse-behavior-communication','medium',null,'Correct. Rhythmic, sharp tail swishing in response to leg aids is a clear communication of irritation or discomfort with that stimulus. It warrants evaluation of leg aid intensity, spur use, and saddle fit.','Rhythmic, sharp tail swishing in direct response to leg aids signals irritation or discomfort with those aids. This is distinct from occasional loose tail movement to dislodge flies — the pattern is the diagnostic information.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_12eb2efe39dc','A displacement behavior differs from a primary behavioral response in that displacement behaviors:','["Appear when a horse is in conflict between competing impulses","Are more extreme and harder to manage","Are only seen in unhandled or feral horses","Result from insufficient desensitization to training equipment"]'::jsonb,'Appear when a horse is in conflict between competing impulses','behavior','horse-behavior-communication','medium',null,'Correct. Displacement behaviors (yawning, pawing, licking and chewing) appear when the horse is in conflict — between flight and staying, between fear and training, between competing motivations. They are not random.','Displacement behaviors appear at the edges of a horse''s tolerance — when the horse is in conflict between competing impulses. Their context-specificity is what makes them diagnostic rather than random fidgeting.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_3b12894f0674','A horse''s back swinging rhythmically under a rider indicates:','["The horse is moving in physical and mental comfort","The horse is bracing against the rider''s position","Impulsion is excessive for the gait","The horse is about to spook or bolt"]'::jsonb,'The horse is moving in physical and mental comfort','behavior','horse-behavior-communication','medium',null,'Correct. A rhythmic, oscillating swing through the back is the sought-after quality in working horses — it indicates physical relaxation and mental availability. Its absence indicates tension.','A horse that swings freely through the back is moving in physical and mental comfort. This swing is the sought-after quality in dressage, working equitation, and horsemanship — its absence in a horse that previously swung freely indicates new tension.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_adb6fb07d957','Reading a horse''s behavioral state BEFORE handling begins is important because:','["It tells the handler what baseline they are working from and what the session''s likely trajectory will be","It is required by competition rules before a class begins","It provides information about the horse''s nutritional status","It replaces the need for veterinary evaluation of behavioral concerns"]'::jsonb,'It tells the handler what baseline they are working from and what the session''s likely trajectory will be','behavior','horse-behavior-communication','medium',null,'Correct. Pre-handling behavioral assessment establishes the session baseline — a horse that is already tense before the saddle comes out has a different starting point than a relaxed horse, and that information should change how the session begins.','Pre-handling behavioral assessment tells the handler what they are starting with — a tense horse and a relaxed horse require different session approaches. Skipping this assessment means working from assumptions rather than current information.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_347d848b5373','What is the most common behavioral reading error made by experienced handlers?','["Skipping pre-handling behavioral assessment because of assumed consistency between sessions","Reading ears instead of muzzle as the primary first signal","Misidentifying excitement as fear in young horses","Overreacting to tail movement in calm environments"]'::jsonb,'Skipping pre-handling behavioral assessment because of assumed consistency between sessions','behavior','horse-behavior-communication','medium',null,'Correct. Experienced handlers most commonly assume a horse is in the same state as yesterday and skip the pre-handling read. A horse changes day to day — and sometimes dramatically — which is exactly why that assessment matters.','The most common behavioral reading error in experienced handlers is assuming consistency between sessions and skipping the pre-handling behavioral check. A horse''s state on any given day may differ significantly from the previous one.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_73d6c155524c','Negative reinforcement is best defined as:','["Removing an unpleasant stimulus immediately after the correct response","Punishing unwanted behavior with a corrective aid","Adding an unpleasant stimulus to discourage incorrect responses","Decreasing the intensity of aids when a horse complies"]'::jsonb,'Removing an unpleasant stimulus immediately after the correct response','behavior','horse-behavior-communication','medium',null,'Correct. Negative reinforcement removes (negative = removal) something unpleasant (reinforcement = increases behavior). The release is the reinforcer in pressure-and-release training.','Negative reinforcement removes an unpleasant stimulus immediately after the correct response, making that response more likely to recur. The release, not the pressure, is what teaches.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_4b69836ead94','In pressure-and-release training, what is the most critical variable?','["The timing of the release","The amount of pressure applied","The type of pressure used (leg, rein, rope)","The duration of each training session"]'::jsonb,'The timing of the release','behavior','horse-behavior-communication','medium',null,'Correct. Release timing — ideally within one to two seconds of the onset of the correct response — is the most critical variable. A late release reinforces the wrong behavior regardless of how appropriate the pressure was.','The timing of the release is the most critical variable. A release even two seconds too late teaches the horse that whatever it was doing at that moment was the desired response, not the intended behavior.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_d6eab1be7bbc','Classical conditioning describes:','["An association formed between a neutral stimulus and a meaningful event","The process of shaping complex behaviors through successive approximations","A punishment system in which pressure follows every incorrect response","The use of food rewards to increase the frequency of desired behaviors"]'::jsonb,'An association formed between a neutral stimulus and a meaningful event','behavior','horse-behavior-communication','medium',null,'Correct. Classical conditioning is the mechanism by which a neutral stimulus, repeatedly paired with a meaningful one, comes to produce the same response as the meaningful stimulus.','Classical conditioning is the formation of an association between a neutral stimulus and a meaningful event. Repeatedly pairing a neutral cue with a meaningful outcome causes the neutral cue to produce the same response as the outcome.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_9518b3402208','Systematic desensitization differs from flooding in that:','["Systematic desensitization exposes the horse at sub-threshold intensity; flooding exposes at full intensity","Systematic desensitization takes longer but flooding produces more stable results","Systematic desensitization requires sedation; flooding does not","Systematic desensitization uses positive reinforcement; flooding uses negative reinforcement"]'::jsonb,'Systematic desensitization exposes the horse at sub-threshold intensity; flooding exposes at full intensity','behavior','horse-behavior-communication','medium',null,'Correct. Systematic desensitization keeps exposure below the horse''s fear threshold, allowing the horse to process and settle. Flooding forces full-intensity exposure and prevents escape — a welfare risk.','Systematic desensitization uses sub-threshold exposure — close enough to notice, not close enough to trigger flight — and progresses incrementally. Flooding uses full-intensity exposure and prevents the horse from escaping.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_c853d15381b7','Positive reinforcement in horse training means:','["Adding something the horse values immediately after the correct response","Providing a pleasant environment for all training sessions","Removing pressure when the horse complies","Giving the horse a break after a difficult exercise"]'::jsonb,'Adding something the horse values immediately after the correct response','behavior','horse-behavior-communication','medium',null,'Correct. Positive reinforcement adds something desirable — usually food — immediately after the desired behavior. The ''positive'' refers to addition (adding something), not to pleasantness.','Positive reinforcement adds something the horse values — typically food — immediately after the correct response. ''Positive'' means addition; ''reinforcement'' means the behavior increases. Timing of delivery is as critical as in negative reinforcement.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_5c75368c60f8','A horse that classically conditions a fear response to a specific piece of equipment has:','["Associated that equipment with a prior negative experience","Genetically inherited a fear of that object","Been incorrectly desensitized to that equipment type","Developed a dominance-based avoidance behavior"]'::jsonb,'Associated that equipment with a prior negative experience','behavior','horse-behavior-communication','medium',null,'Correct. Classical conditioning operates through association. A horse that fears a specific object has learned — through repeated pairing — that the object predicts a negative experience. Desensitization works by replacing that association.','Classical conditioning works through association. A horse that is frightened by specific equipment has associated that equipment with a prior negative experience through repeated pairing. Desensitization replaces this learned fear association.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_8c4c1d8c6c09','Stereotypies are best addressed by:','["Identifying and resolving the management deficit that produced them","Using physical barriers to prevent the behavior","Increasing training frequency to redirect the behavior","Separating the horse from others that may imitate the behavior"]'::jsonb,'Identifying and resolving the management deficit that produced them','behavior','horse-behavior-communication','medium',null,'Correct. Stereotypies are welfare signals produced by chronic management deficits. Blocking the behavior without addressing the deficit leaves the horse in the same compromised welfare state.','Stereotypies are produced by management deficits — inadequate forage, social isolation, confinement. Blocking the behavior without addressing the deficit does not resolve the welfare problem. The only effective intervention addresses the underlying cause.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_52869ad4cbbc','The Five Freedoms framework includes which of the following?','["Freedom to express normal behavior","Freedom from all forms of training pressure","Freedom from all dietary restrictions","Freedom from human handling"]'::jsonb,'Freedom to express normal behavior','behavior','horse-behavior-communication','medium',null,'Correct. Freedom to express normal behavior is one of the Five Freedoms, addressing whether an animal can engage in species-typical social, physical, and behavioral patterns.','Freedom to express normal behavior is one of the Five Freedoms. The five are: freedom from hunger and thirst; freedom from discomfort; freedom from pain, injury, and disease; freedom to express normal behavior; and freedom from fear and distress.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_4ff7045f6c8d','A horse in learned helplessness differs from a genuinely calm horse in that:','["A horse in learned helplessness has stopped responding because its responses have no effect, not because it is settled","A calm horse will never react under any circumstances","A horse in learned helplessness is more responsive to positive stimuli","Learned helplessness only develops in horses with prior pain histories"]'::jsonb,'A horse in learned helplessness has stopped responding because its responses have no effect, not because it is settled','behavior','horse-behavior-communication','medium',null,'Correct. Learned helplessness mimics calm but is a state of shutdown — the horse has stopped responding because trying makes no difference. A genuinely calm horse remains responsive to positive stimuli.','Learned helplessness resembles calm but is fundamentally different: the horse has stopped responding because it has learned that responses have no effect. A genuinely calm horse can still be engaged; a horse in learned helplessness often cannot.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_ff3721114221','Which behavioral need, when chronically unmet, most reliably produces stereotypies in domestic horses?','["Adequate forage access","Sufficient daily exercise","Contact with human handlers","Access to open water sources"]'::jsonb,'Adequate forage access','behavior','horse-behavior-communication','medium',null,'Correct. Inadequate forage access is among the most strongly documented welfare deficits associated with stereotypy development. Horses evolved to graze near-continuously — significant forage restriction is a major stressor.','Inadequate forage access is the management factor most consistently documented as a driver of stereotypy development. Horses evolved to graze near-continuously; significant forage restriction produces the chronic stress that initiates stereotypies.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_e367a19eb34e','What does the approach-and-retreat technique accomplish in systematic desensitization?','["Advances the stimulus only when the horse is calm, retreats before the horse escalates","Moves the horse forward and back to maintain engagement","Alternates between positive and negative reinforcement to build response","Desensitizes the horse to both approach and escape cues simultaneously"]'::jsonb,'Advances the stimulus only when the horse is calm, retreats before the horse escalates','behavior','horse-behavior-communication','medium',null,'Correct. Approach-and-retreat keeps the exposure below the fear threshold by advancing only when the horse is settled and retreating before the horse approaches the threshold — building tolerance incrementally.','Approach-and-retreat is the systematic desensitization technique of advancing only when the horse is calm and retreating before the horse reaches its fear threshold. This keeps exposure sub-threshold and builds tolerance session by session.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_9c120723260a','Classical conditioning is described as operating passively in barn environments. This means:','["Horses form associations through daily routines and environments even without deliberate training","Classical conditioning only works when the horse is actively engaged in training","Passive classical conditioning produces weaker responses than deliberate conditioning","Environmental associations are less stable than trained associations"]'::jsonb,'Horses form associations through daily routines and environments even without deliberate training','behavior','horse-behavior-communication','medium',null,'Correct. Classical conditioning operates continuously — through the smell of a saddle pad, the sound of a gate, a specific location in the arena. Every repeated pairing of stimulus and outcome creates an association, regardless of the handler''s intention.','Classical conditioning operates passively — horses form associations through every repeated pairing they experience, including barn routines, environmental cues, and handling sequences. It does not require deliberate training sessions to operate.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_8c72d266c55e','Why is a horse described as a prey animal?','["It evolved to flee from predators rather than fight them","It is hunted in all wild environments","It prefers open terrain and refuses to enter enclosed spaces","It eats only plants and avoids meat"]'::jsonb,'It evolved to flee from predators rather than fight them','behavior','intro-to-horse-behavior','easy',null,'Correct. Horses evolved where predators were common and their survival strategy is to detect threats early and flee quickly. This shapes every reactive behavior.','Horses are prey animals because their primary survival strategy is to flee from predators. This single fact shapes nearly every reactive behavior.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_f3253e2a6e5c','What is the flight response?','["The instinct to flee suddenly from perceived danger before fully processing the threat","A trained behavior used to move away from leg pressure","The reflex that causes a horse to jump obstacles","The horse''s instinct to approach unfamiliar objects carefully"]'::jsonb,'The instinct to flee suddenly from perceived danger before fully processing the threat','behavior','intro-to-horse-behavior','easy',null,'Correct. The flight response activates before conscious assessment is complete — a horse can be moving before it has fully processed what startled it.','The flight response is the instinctive, pre-conscious impulse to flee. A horse can be in motion before it has fully processed what startled it.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_07a0d4c097e9','Where are a horse''s two blind spots?','["Directly behind the body and directly in front of the face","Directly to the left and right of the head","Above the head and below the hooves","Just behind the shoulders on each side"]'::jsonb,'Directly behind the body and directly in front of the face','behavior','intro-to-horse-behavior','easy',null,'Correct. Both directly behind the body and directly in front of the face (within about four feet) are blind spots. Approaching from either position bypasses the horse''s ability to identify the handler before contact.','The two blind spots: directly behind the body and directly in front of the face within about four feet. Both angles prevent the horse from identifying what is approaching.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_c575ea204f30','What does herd instinct explain about how horses respond to isolation?','["Horses are under genuine biological stress when separated from companions, because the safety system their nervous system depends on has been removed","Horses enjoy brief solitude and seek companionship only at feeding time","Herd instinct only applies to wild horses — domestic horses adapt fully to isolation","Horses become more focused and easier to handle when isolated from distracting companions"]'::jsonb,'Horses are under genuine biological stress when separated from companions, because the safety system their nervous system depends on has been removed','behavior','intro-to-horse-behavior','easy',null,'Correct. Horses evolved as herd animals because multiple animals detect predators more reliably than one. Isolation removes that system and creates genuine biological stress.','Herd instinct is biological, not optional. Isolation removes the safety-detection system horses are wired to depend on, causing genuine stress.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_a717a3b1149d','How many degrees of visual coverage does a horse''s field of vision span?','["Approximately 340 degrees","Approximately 180 degrees","Approximately 270 degrees","Approximately 90 degrees"]'::jsonb,'Approximately 340 degrees','behavior','intro-to-horse-behavior','easy',null,'Correct. A horse''s panoramic vision covers approximately 340 degrees, an adaptation for detecting predators on open plains. Two blind spots account for the remaining coverage.','A horse''s visual field spans approximately 340 degrees — nearly all the way around its body. The remaining area is covered by two blind spots.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_cbf21a46a4c6','Why does the flight response sometimes activate before the horse seems to have seen or heard anything?','["The response is processed through the amygdala before the conscious brain can complete a full assessment — speed was the survival advantage","Horses can detect ultrasonic frequencies that humans cannot hear","The horse responds to chemical signals from other horses before detecting the threat itself","Horses have faster nerve conduction than most other mammals"]'::jsonb,'The response is processed through the amygdala before the conscious brain can complete a full assessment — speed was the survival advantage','behavior','intro-to-horse-behavior','easy',null,'Correct. The threat-detection pathway activates faster than conscious processing. A horse that hesitated to assess before running was more likely to be caught.','The flight response routes through the brain''s threat center before the frontal cortex completes assessment. This speed was a survival advantage — hesitation could mean being caught.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_0a0aa9e45c6d','What has thousands of years of domestication done to the horse''s prey animal instincts?','["It has not overwritten those instincts — a well-trained horse has learned to override the flight response through trust and habituation, but the instinct remains accessible under stress","It has eliminated the flight response in domesticated breeds","It has replaced instinctual behavior with learned responses entirely","It has reduced the horse''s visual field as vigilance is no longer needed"]'::jsonb,'It has not overwritten those instincts — a well-trained horse has learned to override the flight response through trust and habituation, but the instinct remains accessible under stress','behavior','intro-to-horse-behavior','easy',null,'Correct. Domestication made horses tractable but did not remove prey animal instincts. The flight response remains accessible in any novel, painful, or high-stress situation.','Domestication did not overwrite prey animal instincts. A well-trained horse has learned to suppress the flight response through trust — but the instinct is always present under stress, pain, or novelty.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_9638dbf7e5f6','What is the most dangerous position relative to a horse from the standpoint of kick force?','["Several feet directly behind the horse, where a kick reaches with full momentum","Directly beside the horse at the hip","At a distance beyond six feet directly behind","Directly in front of the face"]'::jsonb,'Several feet directly behind the horse, where a kick reaches with full momentum','behavior','intro-to-horse-behavior','easy',null,'Correct. A kick delivered at close range behind the horse contacts before full momentum builds. At several feet directly behind, the kick has full extension and maximum force.','The most dangerous position: several feet directly behind. At that distance, the hindleg reaches with full momentum. Close proximity behind the horse actually reduces the force a kick can generate.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_43482a01576a','Why do horses seek the company of other horses even in domestic management?','["Multiple herd members provide more comprehensive predator detection than a single animal — this is an evolved survival advantage","Horses are social by preference but manage equally well alone","Horses seek companionship only as a learned behavior reinforced by feeding routines","Horses bond to humans as an equivalent substitute for herd companions"]'::jsonb,'Multiple herd members provide more comprehensive predator detection than a single animal — this is an evolved survival advantage','behavior','intro-to-horse-behavior','easy',null,'Correct. Herd living is a survival strategy. More animals mean more eyes, ears, and nostrils monitoring for predators. This wiring persists in domestic horses.','Herd instinct evolved because groups detect predators more reliably than individuals. The safety benefit is biological, not merely social preference.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_438a2fb7a4ce','A horse that is reluctant to enter a dark barn aisle or a trailer is most likely expressing:','["A natural prey animal wariness of enclosed spaces where escape routes are limited","Stubbornness or lack of training","A preference for outdoor environments formed through habituation","A specific phobia that requires veterinary assessment"]'::jsonb,'A natural prey animal wariness of enclosed spaces where escape routes are limited','behavior','intro-to-horse-behavior','easy',null,'Correct. Enclosed spaces limit flight options — the primary survival mechanism. Reluctance to enter them is a predictable expression of prey animal instinct, not defiance.','Reluctance to enter enclosed spaces is a predictable prey animal response. Enclosed areas restrict flight options. Understanding this frames the behavior correctly.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_b1281de08a30','Ears pinned flat against the neck indicate:','["A clear aggression warning — a bite or kick may follow","The horse is listening to something behind it","The horse is relaxed and resting","The horse is focused on the handler and paying close attention"]'::jsonb,'A clear aggression warning — a bite or kick may follow','behavior','intro-to-horse-behavior','easy',null,'Correct. Ears pressed tightly flat against the neck, combined with muscle tension at the base, are a direct aggression warning. This signal almost never appears without additional body tension.','Pinned ears — pressed hard and flat against the neck — signal aggression. Loosely turned-back ears signal listening or resting. The difference is the degree of muscle tension.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_b51c60e8fcbf','What do loosely backward ears indicate?','["The horse is relaxed and listening to something behind it, or attending to a rider","The horse is about to kick","The horse is in pain","The horse is preparing to run"]'::jsonb,'The horse is relaxed and listening to something behind it, or attending to a rider','behavior','intro-to-horse-behavior','easy',null,'Correct. Loosely turned-back ears are a neutral signal. The horse is monitoring something behind it or attending to a rider. Only ears pressed hard and flat against the neck signal aggression.','Loosely backward ears are neutral — the horse is listening behind it or attending to a rider. Aggression warning = ears pressed tightly flat against the neck with visible base tension.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_0e5e45d3f66d','Visible white sclera around the edge of a horse''s iris indicates:','["A high-fear state — the horse has moved past alert into active fear","The horse is of a breed with naturally prominent eyes","Extreme relaxation in a horse that trusts its handler completely","Eye irritation requiring veterinary assessment"]'::jsonb,'A high-fear state — the horse has moved past alert into active fear','behavior','intro-to-horse-behavior','easy',null,'Correct. When arousal reaches a high-fear level, the muscles around the eye tighten and the eye opens wide enough to show the white sclera. This is called a ''hard eye'' and indicates the horse is at risk of explosive movement.','Visible whites of the eye — called a ''hard eye'' — indicate high-fear arousal. The horse has moved past alert into active fear. This is a significant safety signal.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_09c0ee407c03','A soft exhale through loose nostrils, often combined with a slight lowering of the head, indicates:','["The horse is releasing tension and returning toward a calmer state","The horse is about to make a sudden movement","The horse is reacting to an unfamiliar scent in the environment","The horse is fatigued and needs to rest"]'::jsonb,'The horse is releasing tension and returning toward a calmer state','behavior','intro-to-horse-behavior','easy',null,'Correct. A soft blow through relaxed nostrils is one of the most reliable relaxation signals. Combined with head-lowering, licking and chewing, or a yawn, it indicates the horse is actively decompressing.','A soft exhale through loose nostrils is a relaxation signal — the horse has finished processing something and is returning toward calm. Combined with head-lowering, it is one of the clearest signs of decompression.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_2891c6af8693','What does a whinny (neigh) primarily communicate?','["A long-range contact call most often used by a horse separated from companions or searching for a familiar presence","A short-range greeting directed at a known companion","A warning signal used in conflict situations","A signal of distress indicating immediate medical need"]'::jsonb,'A long-range contact call most often used by a horse separated from companions or searching for a familiar presence','behavior','intro-to-horse-behavior','easy',null,'Correct. The whinny is long-range and highly individual — horses can recognize a specific companion''s whinny. It communicates social need rather than emergency distress.','The whinny is a long-range contact call used when separated from companions or searching for a familiar presence. It is not a short-range greeting (that is the nicker) or a conflict warning (that is the squeal).') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_746293a00a4b','What does a horse''s topline communicate about its emotional state?','["A soft, relaxed topline indicates a nervous system not in threat-response mode; a braced or hollow topline indicates tension even if the head and ears appear calm","The topline reflects only the horse''s level of physical fitness, not its emotional state","A raised topline is always a sign of engagement and enthusiasm in a working horse","Topline tension only appears in horses that have experienced physical pain or injury"]'::jsonb,'A soft, relaxed topline indicates a nervous system not in threat-response mode; a braced or hollow topline indicates tension even if the head and ears appear calm','behavior','intro-to-horse-behavior','easy',null,'Correct. The topline is one of the most consistent indicators of underlying tension. A horse can have relatively normal-looking ears while carrying a braced, hollow back — the topline reads the full-body state.','The topline is the most reliable full-body tension indicator. A braced or hollow topline indicates tension throughout the horse''s nervous system, even when the head and ears look relatively settled.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_c43b25276b17','A squeal in horse communication most commonly occurs in what context?','["Conflict or boundary-setting — horses meeting across a fence, resource competition, or breeding interactions","A friendly greeting between horses in the same herd","A distress call used when a horse is separated from the herd","A response to an unfamiliar human presence"]'::jsonb,'Conflict or boundary-setting — horses meeting across a fence, resource competition, or breeding interactions','behavior','intro-to-horse-behavior','easy',null,'Correct. The squeal is a sharp warning burst used in conflict contexts. In a handling situation, a squeal often accompanies pinned ears and may precede a kick or bite.','The squeal is a conflict vocalization — boundary-setting between horses. In handling, it is a warning that may precede physical aggression.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_5bfaf691307e','What does hindquarters angled toward a handler communicate?','["A specific warning that the horse is presenting its primary defensive weapon and a kick is possible","The horse is simply repositioning to face away from a distraction","A relaxation signal — the horse is comfortable enough to show its back","Normal herd behavior that has no specific communicative meaning in handling contexts"]'::jsonb,'A specific warning that the horse is presenting its primary defensive weapon and a kick is possible','behavior','intro-to-horse-behavior','easy',null,'Correct. Hindquarters deliberately angled toward a person is intentional communication: the horse is presenting its most powerful defensive tool and warning the handler to move away.','Hindquarters turned toward a handler is a direct warning signal — the horse is presenting its most powerful defensive weapon. The correct response is to reposition alongside the horse''s body, not step closer.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_43e6aae026cc','What does a groan during girthing or movement most likely indicate?','["Physical discomfort — a groaning horse during these activities should be assessed for pain sources","The horse is clearing its airway in a normal respiratory pattern","The horse is vocalizing contentment similar to a cat''s purr","Reluctance and evasion of work that resolves with consistent training"]'::jsonb,'Physical discomfort — a groaning horse during these activities should be assessed for pain sources','behavior','intro-to-horse-behavior','easy',null,'Correct. Groaning carries a specific meaning: physical discomfort or significant effort. A horse that groans consistently during girthing or saddling should be evaluated for back or girth area pain.','The groan is a pain or significant-effort signal. A horse that groans during girthing, saddling, or movement should be assessed for a physical source before the behavior is attributed to evasion.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_1ef74fc468ce','A nicker is best described as:','["A short-range, low, affiliative call directed at a known companion or person associated with positive interaction","A long-range contact call used when separated from the herd","A warning vocalization used in conflict situations","A sound made only during feeding that has no broader social meaning"]'::jsonb,'A short-range, low, affiliative call directed at a known companion or person associated with positive interaction','behavior','intro-to-horse-behavior','easy',null,'Correct. The nicker is the most affiliative of horse vocalizations — a soft, low vibration directed at a trusted companion or person. Many horses develop a personalized nicker greeting for handlers they trust.','The nicker is a short-range affiliative call — a soft, low vibration directed at a companion or trusted person. It is the opposite of a conflict vocalization.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_feddcf421d52','What does a horse with low head, soft eyes, a loose lower lip, and one resting hind leg demonstrate?','["Genuine relaxation — a nervous system not in active threat-detection mode","Alertness to a nearby stimulus","Hunger or a request to be fed","The early stage of a lameness condition"]'::jsonb,'Genuine relaxation — a nervous system not in active threat-detection mode','behavior','intro-to-horse-behavior','easy',null,'Correct. Low head, soft eyes, a loose lower lip, and a resting hind leg are the consistent physical signatures of genuine calm. These are the markers of a horse accessible to handling and training.','Low head, soft eyes, loose lower lip, and a resting hind leg are all relaxation markers. Together they indicate a horse whose nervous system is not in active threat-detection mode.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_64d5de12d63e','What is the freeze that precedes flight, and why is it dangerous to misread?','["A sudden complete stillness with locked muscles and wide eyes that immediately precedes explosive movement — misread as settling, it places the handler in the path of a bolt or spin","A brief pause between gaits that is normal in a well-balanced horse","A calming signal indicating the horse has resolved its concern about a stimulus","A training response where the horse waits for the next cue before moving"]'::jsonb,'A sudden complete stillness with locked muscles and wide eyes that immediately precedes explosive movement — misread as settling, it places the handler in the path of a bolt or spin','behavior','intro-to-horse-behavior','easy',null,'Correct. The freeze lasts less than a second before the horse bolts, spins, or rears. A handler who steps toward a horse in this state is directly in the path of explosive movement.','The freeze is not settling — it is the final moment before explosive movement. Locked muscles, rigid neck, and wide eyes that suddenly go still are the signal to give room and reduce all pressure immediately.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_c1a92b5eae9d','After a major fear response, why should demanding work not resume immediately even when the horse appears calm?','["Stress hormones released during fear remain elevated in the bloodstream for several minutes, making the horse much easier to re-trigger than it appears","Horses need physical rest after any emotional event before their muscles can function correctly","The horse has lost confidence and needs several sessions to rebuild trust before working","The handler needs time to assess whether the triggering stimulus is still present"]'::jsonb,'Stress hormones released during fear remain elevated in the bloodstream for several minutes, making the horse much easier to re-trigger than it appears','behavior','intro-to-horse-behavior','easy',null,'Correct. Adrenaline and cortisol take several minutes to clear. A horse that appears settled minutes after a fright is still running elevated body chemistry and will re-trigger much more easily.','Stress hormones from a fear response stay elevated for several minutes. The horse may look calm but is still biochemically primed to re-trigger. Allow a real recovery period before resuming demanding work.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_5b6c68386296','A horse in the alert state has:','["Detected something worth assessing and shifted to active processing — ears sharply forward, head elevated, nostrils slightly flared, weight forward","Moved into a fear state and is preparing for immediate flight","Settled after a previous arousal and is returning to calm","Directed its attention fully to the handler and is ready for work"]'::jsonb,'Detected something worth assessing and shifted to active processing — ears sharply forward, head elevated, nostrils slightly flared, weight forward','behavior','intro-to-horse-behavior','easy',null,'Correct. The alert state is a transition window. The horse is actively assessing a stimulus. This state resolves either toward calm (if the stimulus is assessed as non-threatening) or toward fear (if pressure is added).','The alert state means the horse has detected something and shifted to active processing. It is a transition window, not a danger state — it can resolve toward calm or escalate toward fear depending on how the handler responds.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_70687c01b6cd','What is the most effective handler response when a horse enters an alert state?','["Remain calm, maintain consistent contact, and give the horse time to complete its assessment of the stimulus","Apply strong pressure to redirect the horse''s attention back to the handler immediately","Move the horse past the stimulus quickly to prevent extended focus on it","Stop all work and remove the horse from the situation entirely"]'::jsonb,'Remain calm, maintain consistent contact, and give the horse time to complete its assessment of the stimulus','behavior','intro-to-horse-behavior','easy',null,'Correct. A calm, consistent handler presence signals to the horse that the human is not alarmed — the most useful piece of information available while the horse makes its own assessment.','In the alert window, the handler''s calm signals to the horse that the stimulus is not a genuine threat. Adding pressure or abrupt movement sends the opposite message and tends to accelerate arousal.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_dc718f01c6c8','What does dominant body language directed at a handler most often communicate?','["That the horse''s space is being encroached upon or a resource is being contested — it is communication with specific content, not a personal challenge","That the horse is dangerous and handling should cease permanently","That the horse has an underlying medical condition causing irritability","A personality trait that cannot be modified through training"]'::jsonb,'That the horse''s space is being encroached upon or a resource is being contested — it is communication with specific content, not a personal challenge','behavior','intro-to-horse-behavior','easy',null,'Correct. Dominant or aggressive signals are not random. They communicate a specific message about space or resource priority. Understanding the message determines the correct response.','Dominant behavior toward a handler communicates space or resource priority — not random aggression. The content of the communication determines the correct response.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_2f7cec6c246e','What distinguishes the fearful/flight-ready state from the alert state?','["In the fearful state, the horse is no longer fully processing the handler''s aids — the survival response takes priority and the horse may react to things it normally ignores","The fearful state is simply a more intense version of alertness with no behavioral difference","In the fearful state the horse becomes easier to handle because it focuses entirely on the handler","The fearful state is identified solely by the presence of vocalization"]'::jsonb,'In the fearful state, the horse is no longer fully processing the handler''s aids — the survival response takes priority and the horse may react to things it normally ignores','behavior','intro-to-horse-behavior','easy',null,'Correct. In the fearful state, training recedes and survival instinct takes over. The horse may react to its own shadow or a sound it normally ignores. Adding pressure at this point typically accelerates the response.','In the fearful state, training recedes and survival instinct takes priority. The horse stops fully processing aids and may react to normally-ignored stimuli. This is the critical difference from the alert state.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_7209578a767f','What does a rising head carriage indicate about a horse''s arousal level?','["The horse is elevating its visual field to scan for threats — head raising is one of the first signs of increasing arousal","High head carriage is a trained posture and has no behavioral significance","A horse with a raised head is more relaxed than one with a lowered head","Head carriage reflects only physical conformation and does not indicate emotional state"]'::jsonb,'The horse is elevating its visual field to scan for threats — head raising is one of the first signs of increasing arousal','behavior','intro-to-horse-behavior','easy',null,'Correct. As arousal increases, the head comes up — the horse is raising its visual field to scan a wider area for threats. Head-lowering indicates the opposite: a return toward relaxation and reduced arousal.','Rising head carriage is one of the earliest arousal signals. The horse elevates its visual field to scan for threats. A returning head-drop indicates de-escalation back toward calm.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_e2590fda68ed','What do licking and chewing, yawning, and shaking out the neck indicate when observed after a tense moment?','["Active decompression — the horse is releasing stored tension and returning toward a calmer state","Hunger, fatigue, and physical discomfort respectively","Random behaviors with no specific communicative content","Signs that the horse did not understand what was being asked of it"]'::jsonb,'Active decompression — the horse is releasing stored tension and returning toward a calmer state','behavior','intro-to-horse-behavior','easy',null,'Correct. Licking and chewing, yawning, and neck shaking are decompression signals — the horse is actively releasing tension. These are positive signs that the horse is returning toward a trainable, receptive state.','Licking and chewing, yawning, and neck shaking are decompression signals — the horse is releasing tension and returning toward calm. They are positive indicators, not signs of confusion or discomfort.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_040669ff519a','What does visible muscle trembling under the skin — especially over the flanks — indicate?','["Very high nervous arousal with imminent possible flight or fight response","Normal muscle activity during relaxed standing at rest","The horse is cold or fatigued from physical exertion","A mild relaxation response similar to a dog wagging its tail"]'::jsonb,'Very high nervous arousal with imminent possible flight or fight response','behavior','intro-to-horse-behavior','easy',null,'Correct. Visible trembling under the skin, particularly over the flanks, signals extremely high nervous arousal. The horse''s muscles are priming for explosive movement — this is an immediate warning signal for handlers.','Muscle trembling under the skin, especially over the flanks, signals very high nervous arousal. The horse is physiologically primed for explosive movement. This is a serious warning signal, not a relaxation response.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_37b0022c32bd','The correct side and position from which to approach a horse is:','["An angle toward the left (near) shoulder — where the horse can see and track the handler''s full approach","Directly from behind at a slow walk — so the horse hears the approach before contact","Directly from the front so the horse can see the handler''s face clearly","From the right side only — the left side is reserved for mounting"]'::jsonb,'An angle toward the left (near) shoulder — where the horse can see and track the handler''s full approach','behavior','intro-to-horse-behavior','easy',null,'Correct. Approaching at an angle toward the left shoulder keeps the handler out of both blind spots and in the horse''s visual field throughout the approach.','Correct approach: angle toward the left shoulder. This keeps the handler visible to the horse throughout the entire approach and avoids both blind spots.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_985626a2324f','Why should a handler speak to a horse before making physical contact?','["To give the horse an auditory signal that confirms a familiar presence before touch, preventing a startle response","To establish dominance before the handling session begins","To assess whether the horse is responsive and in a workable state","To comply with standard equine facility safety regulations"]'::jsonb,'To give the horse an auditory signal that confirms a familiar presence before touch, preventing a startle response','behavior','intro-to-horse-behavior','easy',null,'Correct. Speaking before touching gives the horse''s nervous system the moment it needs to shift from ''unknown stimulus approaching'' to ''known safe presence.'' This one habit prevents the majority of startle-response injuries.','Speaking before touching provides an auditory cue that allows the horse to shift from ''unknown stimulus'' to ''known presence'' before contact. This prevents the startle response that leads to most contact injuries.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_ab615dcb4dab','What are the three requirements for correctly tying a horse?','["Solid permanent structure, at or above wither height, with a quick-release knot","Any fence post, below the chest for stability, with a double knot for security","A gate or fence rail, at knee height, with a standard half-hitch","A crossbar, at mouth height, with any knot the handler prefers"]'::jsonb,'Solid permanent structure, at or above wither height, with a quick-release knot','behavior','intro-to-horse-behavior','easy',null,'Correct. Solid structure prevents pulling loose; wither height or above prevents the horse getting a leg over the rope; quick-release allows one-handed freeing under full tension.','All three tying requirements: solid permanent structure (not a rail or gate that can pull loose), at or above wither height (prevents leg-over-rope), quick-release knot (can be freed under full tension with one hand).') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_29dbe279c367','When a horse pulls back against a tie, the correct handler response is:','["Do not approach until the horse has fully settled — a horse pulling back is in full panic flight response","Approach immediately and release the quick-release knot to prevent injury","Hold the lead rope manually to prevent the horse from putting backward pressure on the tie","Push the horse forward firmly to prevent the pull-back from becoming a habit"]'::jsonb,'Do not approach until the horse has fully settled — a horse pulling back is in full panic flight response','behavior','intro-to-horse-behavior','easy',null,'Correct. A horse pulling back is in a full flight panic state — approaching while it is actively panicking puts the handler in a dangerous position. Wait for full settlement.','A horse pulling back against a tie is in full flight panic. Approaching during active pulling is dangerous. Wait until the horse has fully settled before approaching.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_372678bbd679','The correct sequence for releasing a horse into a paddock is:','["Walk in with the horse, turn the horse to face the gate, step back from the hindquarters, then remove the halter","Open the gate, unclip the lead rope, and allow the horse to walk in on its own","Turn the horse away from the gate before releasing so it moves away from the handler","Remove the halter at the gate entrance before entering the paddock"]'::jsonb,'Walk in with the horse, turn the horse to face the gate, step back from the hindquarters, then remove the halter','behavior','intro-to-horse-behavior','easy',null,'Correct. Turning the horse to face the gate before halter removal prevents the spin-and-kick pattern that causes most turn-out injuries. Stepping back clears the handler from the departure path.','Correct release sequence: walk in, turn horse to face gate, step back from hindquarters, then remove halter. This prevents the spin toward the gate that puts the handler in the path of departing hindlegs.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_111bce8bcfe1','When leading a horse, the handler''s correct position is:','["At the horse''s shoulder — not in front pulling, nor at the hip where the horse can crowd forward","Directly in front of the horse to encourage it to follow","At the horse''s hip so the handler can see the full length of the horse while walking","As far behind the head as the lead rope allows for maximum safety distance"]'::jsonb,'At the horse''s shoulder — not in front pulling, nor at the hip where the horse can crowd forward','behavior','intro-to-horse-behavior','easy',null,'Correct. Shoulder position gives the handler control, keeps them out of the kick zone, and prevents the horse from drifting forward and crowding. Being pulled from the front or pushed from behind are both unsafe positions.','Lead position = horse''s shoulder. In front creates pulling and loses control; at the hip allows the horse to crowd forward. Shoulder position provides control and keeps the handler in the horse''s visual field.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_89fd7b6a9e3b','What does ''speaking before touching'' prevent specifically in horse handling?','["The startle response — which occurs when contact registers as an unexpected stimulus from an unidentified source","Dominance-seeking behavior that emerges when a horse is not warned of approach","Separation anxiety in horses that have bonded strongly to a single handler","The freeze-before-flight response that occurs when horses are surprised"]'::jsonb,'The startle response — which occurs when contact registers as an unexpected stimulus from an unidentified source','behavior','intro-to-horse-behavior','easy',null,'Correct. A horse touched without warning processes the contact as an unknown stimulus — potentially a predator striking. A verbal cue before contact shifts the stimulus from ''unknown'' to ''known safe presence.''','Speaking before touching prevents the startle response. Without a warning cue, contact from an unseen source registers as an unknown stimulus — potentially threatening. A vocal cue reframes the contact before it occurs.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_c41b7aa734ae','Before putting a halter on a horse, the first step is to:','["Slip the lead rope over the horse''s neck to create a light hold before haltering begins","Clip the lead rope to the halter ring and then bring both toward the horse together","Hold the lead rope in the free hand and keep it clear of the horse until the halter is buckled","Attach the halter first, then return to collect the lead rope from where it was left"]'::jsonb,'Slip the lead rope over the horse''s neck to create a light hold before haltering begins','behavior','intro-to-horse-behavior','easy',null,'Correct. Slipping the rope over the neck first creates a light hold before the halter goes on. This prevents the horse from walking away if it shifts position during the haltering process.','The rope goes over the neck first — creating a light hold before haltering begins. Without this, a horse that steps away mid-process is free to leave entirely.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_88bdd2968b92','A horse that crowds into the handler''s space while being led is most effectively corrected by:','["Reversing direction — turning back the way they came applies spatial pressure that interrupts the crowding","Pushing the horse sideways with the shoulder while continuing forward","Stopping and standing in place until the horse moves away on its own","Continuing forward while shortening the lead rope to limit how far the horse can drift"]'::jsonb,'Reversing direction — turning back the way they came applies spatial pressure that interrupts the crowding','behavior','intro-to-horse-behavior','easy',null,'Correct. A reversal of direction changes the spatial dynamic and interrupts the crowding without direct confrontation. A horse that is crowding is using spatial pressure; the reversal redirects it.','Crowding is most effectively corrected by reversing direction — the change applies spatial pressure without confrontation. Allowing crowding to continue establishes it as acceptable leading behavior.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_87ca43b4304a','Ground handling skills are most accurately described as:','["Basic to all horse interaction, no matter the riding style or experience level — the same behavior rules apply on the ground and under saddle","A separate skill set from ridden work, mostly for handlers who do not ride","A starter topic that riders no longer need to use after they gain experience","The responsibility of barn staff rather than riders in most competition settings"]'::jsonb,'Basic to all horse interaction, no matter the riding style or experience level — the same behavior rules apply on the ground and under saddle','behavior','intro-to-horse-behavior','easy',null,'Correct. Ground handling and ridden work use the same behavior rules in different settings. How a horse is handled on the ground affects how it responds under saddle.','Ground handling is not separate from riding. The same behavior rules apply in both settings. How a horse is handled from the ground affects how it responds under saddle.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_aff176ad7c3a','Where does most fiber digestion occur in the horse?','["The hindgut — cecum and large colon","The stomach","The small intestine","The liver"]'::jsonb,'The hindgut — cecum and large colon','health','equine-nutrition','medium',null,'Correct. Horses are hindgut fermenters — the cecum and large colon are where microbial fermentation breaks down fiber into energy.','The horse is a hindgut fermenter. Most fiber digestion happens in the cecum and large colon through microbial fermentation — not in the stomach or small intestine.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_083ba0187edf','The horse''s stomach is best described as:','["Small and fast-emptying, designed for near-continuous small meals","Large and slow-emptying, suited to twice-daily feeding","Similar in capacity to the rumen of cattle","Capable of efficiently digesting large amounts of starch"]'::jsonb,'Small and fast-emptying, designed for near-continuous small meals','health','equine-nutrition','medium',null,'Correct. The horse''s stomach holds approximately 8–15 liters and empties continuously — it is designed for frequent small meals, not large infrequent ones.','The horse''s stomach is small relative to body size and empties continuously. Horses should receive frequent small amounts of forage, not large meals.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_81d6b214a77e','What is the cecum''s primary role in equine digestion?','["The first chamber of hindgut fermentation where microbial fiber breakdown begins","Producing digestive enzymes for protein absorption","Absorbing vitamins and minerals from concentrate","Storing bile to emulsify dietary fat"]'::jsonb,'The first chamber of hindgut fermentation where microbial fiber breakdown begins','health','equine-nutrition','medium',null,'Correct. The cecum is where the hindgut microbiome begins its fermentation of dietary fiber — the process that produces much of the horse''s energy.','The cecum is where microbial fermentation of fiber begins. It is the first and largest chamber of the hindgut and the foundation of the horse''s fiber digestion.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_9130d3ea1bb8','What happens when excess starch from large grain meals bypasses the small intestine and reaches the hindgut?','["Rapid fermentation produces lactic acid, lowering pH and causing hindgut acidosis","The hindgut microbes convert it to additional volatile fatty acids with no negative effects","The excess starch is stored in the cecum for later use","The starch is excreted undigested without causing digestive disruption"]'::jsonb,'Rapid fermentation produces lactic acid, lowering pH and causing hindgut acidosis','health','equine-nutrition','medium',null,'Correct. Excess starch in the hindgut is rapidly fermented, producing lactic acid that lowers pH, kills beneficial microorganisms, and can cause colic and laminitis.','Excess starch reaching the hindgut causes rapid fermentation and lactic acid production — lowering pH, disrupting microbial populations, and increasing colic and laminitis risk.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_e9c186057396','A horse''s minimum daily forage requirement (as a percentage of body weight) is:','["1.5% of body weight in dry matter","0.5% of body weight in dry matter","3% of body weight in dry matter","10% of body weight in dry matter"]'::jsonb,'1.5% of body weight in dry matter','health','equine-nutrition','medium',null,'Correct. The minimum forage recommendation is 1.5% of body weight in dry matter daily. For a 1,100-lb horse, that is approximately 16 pounds of hay.','The minimum forage recommendation is 1.5% of body weight per day in dry matter. This is a specific, testable figure — know the percentage and be able to calculate it for a given body weight.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_3527f9bf15e0','Why is it important that horses have access to forage throughout the day rather than just at scheduled meals?','["The stomach produces acid continuously and forage is needed to buffer it","Horses digest fiber faster when fed small frequent amounts","Scheduled meals cause horses to become anxious between feedings","The hindgut only functions when forage is continually entering it"]'::jsonb,'The stomach produces acid continuously and forage is needed to buffer it','health','equine-nutrition','medium',null,'Correct. The horse''s stomach produces acid continuously whether or not food is present. Extended periods without forage leave the stomach lining exposed to acid damage — the mechanism behind gastric ulcers.','The horse''s stomach produces acid continuously. Without forage to buffer it, the squamous mucosa is exposed to acid damage. This is the primary reason continuous forage access is essential, not just the fiber supply.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_a3fc5be594f8','What are volatile fatty acids (VFAs) in equine nutrition?','["Energy compounds produced by hindgut fermentation of fiber","Toxic byproducts of grain overconsumption","Fats found in high-oil feed supplements","Acids in the stomach that begin protein digestion"]'::jsonb,'Energy compounds produced by hindgut fermentation of fiber','health','equine-nutrition','medium',null,'Correct. Volatile fatty acids (acetate, propionate, butyrate) are the primary energy compounds produced when the hindgut microbiome ferments dietary fiber — supplying much of the horse''s daily energy needs.','Volatile fatty acids are the energy-yielding compounds produced by microbial fermentation of fiber in the hindgut. They are the primary energy source for horses eating a forage-based diet.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_c275bc931297','Hindgut acidosis in horses is caused by:','["Excess starch reaching the hindgut, where rapid fermentation produces lactic acid","Too much forage disrupting the hindgut''s absorption capacity","High protein intake overloading the cecum''s microbial balance","Dehydration concentrating normal fermentation byproducts"]'::jsonb,'Excess starch reaching the hindgut, where rapid fermentation produces lactic acid','health','equine-nutrition','medium',null,'Correct. Hindgut acidosis occurs when excess starch reaches the cecum and large colon, where it is rapidly fermented — producing lactic acid that lowers pH and disrupts the microbial population.','Hindgut acidosis is caused by excess starch reaching the hindgut, where rapid fermentation produces lactic acid. This drops hindgut pH, damages the mucosal lining, kills beneficial bacteria, and is associated with colic and laminitis.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_334c055c484e','Which type of hay is most appropriate for the majority of adult horses at maintenance?','["Grass hay (timothy, orchardgrass, bermudagrass)","Legume hay (alfalfa, clover)","Mixed hay with 60% alfalfa","Any hay regardless of type, as long as the horse eats it"]'::jsonb,'Grass hay (timothy, orchardgrass, bermudagrass)','health','equine-nutrition','medium',null,'Correct. Grass hays are lower in protein and calories than legume hays, making them appropriate for most adult horses at maintenance, including those at risk for metabolic conditions.','Grass hays are the appropriate forage base for most adult horses at maintenance. They are lower in sugar and protein than legume hays, reducing metabolic risk.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_3d69a93bd7e4','Legume hay (alfalfa, clover) is most appropriate for which category of horse?','["Horses in heavy work, young growing horses, or lactating mares","Adult horses at rest or in light work","Horses with a history of laminitis or metabolic syndrome","Senior horses with reduced caloric needs"]'::jsonb,'Horses in heavy work, young growing horses, or lactating mares','health','equine-nutrition','medium',null,'Correct. Legume hays are significantly higher in protein, calcium, and caloric density — appropriate for horses with high energy or protein demands.','Legume hays are appropriate for horses with high energy or protein demands: performance horses, growing horses, and broodmares in late gestation and lactation. They are too energy-dense for most horses at maintenance.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_645f13a8f5e9','Hay quality is most accurately determined by:','["Laboratory forage analysis measuring protein, energy, NSC, and minerals","Color alone — bright green hay is always high nutritional quality","The weight of the bale — heavier bales contain more nutrition","Visual leaf-to-stem ratio only"]'::jsonb,'Laboratory forage analysis measuring protein, energy, NSC, and minerals','health','equine-nutrition','medium',null,'Correct. Forage analysis provides the actual quantitative data on nutrient content. Visual assessment is a useful starting point but cannot reliably determine NSC, protein, or mineral levels.','Laboratory forage analysis is the only reliable way to know what a specific hay provides. Visual assessment gives preliminary information but cannot accurately measure NSC, crude protein, or mineral content.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_a6fe91fae48c','What is the significance of non-structural carbohydrates (NSC) in hay for horses at metabolic risk?','["NSC above 10–12% can trigger laminitis in susceptible horses","NSC above 10% improves energy supply for all horses","NSC levels below 5% indicate spoiled or unusable hay","NSC does not affect metabolic health when hay is fed in correct amounts"]'::jsonb,'NSC above 10–12% can trigger laminitis in susceptible horses','health','equine-nutrition','medium',null,'Correct. For horses with EMS, PPID, or prior laminitis, an NSC level above 10–12% in hay significantly elevates laminitis risk. Target hay with NSC below 10% for these horses.','NSC (sugars and starches) above 10–12% in hay elevates laminitis risk for horses with metabolic conditions. These horses require tested hay with confirmed low NSC, not visual assessment.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_cb1ad44e13b6','Why should hay be fed by weight rather than by flake?','["Flake weight varies significantly between species and bales — feeding by count does not ensure consistent intake","Horses digest hay more efficiently when it is weighed before feeding","Flake counts only work with baled hay, not round bales","Weighing hay prevents it from drying out between feedings"]'::jsonb,'Flake weight varies significantly between species and bales — feeding by count does not ensure consistent intake','health','equine-nutrition','medium',null,'Correct. A flake of alfalfa can weigh twice what a flake of timothy weighs from a different bale. Feeding by flake count without knowing flake weight produces inconsistent and potentially inadequate intake.','Flake weight varies significantly between hay species and individual bales. Feeding by flake count means the horse''s actual intake is unknown. A scale is the only way to ensure consistent dry matter delivery.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_3dba012ffd85','Spring pasture can be dangerous for metabolically at-risk horses because:','["It is extremely high in non-structural carbohydrates, which can trigger laminitis","It lacks the protein content horses need in the growing season","It grows too quickly for horses to eat in appropriate amounts","It causes dehydration due to high water content"]'::jsonb,'It is extremely high in non-structural carbohydrates, which can trigger laminitis','health','equine-nutrition','medium',null,'Correct. Lush spring or rapidly growing grass is very high in NSC — a primary laminitis trigger for horses with EMS, PPID, or prior laminitis history.','Spring and rapidly growing pasture is extremely high in NSC. For horses with metabolic conditions, this NSC load can trigger laminitis even when access is visually ''managed.'' Pasture NSC testing is the only reliable assessment.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_7eaf822079b1','Which visual characteristic indicates that hay may have been baled at too high a moisture content?','["Musty smell and presence of visible mold","Bright green color with fine, leafy texture","Slightly dusty appearance when shaken","Yellow or faded color from sun bleaching"]'::jsonb,'Musty smell and presence of visible mold','health','equine-nutrition','medium',null,'Correct. Hay baled too wet heats internally during curing, producing mold. A musty smell and visible mold are primary signs — moldy hay should not be fed.','Hay baled at too high moisture content heats internally during storage, producing mold. A musty smell or visible mold indicates this — moldy hay should not be fed.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_4a88397a283d','Mixed hay (grass-alfalfa blend) has which characteristic that makes it especially important to test?','["Its nutritional content varies significantly depending on species ratio, cutting, and growing conditions","It always provides the ideal nutrient profile for all adult horses","Its high fiber content makes NSC levels irrelevant","It is lower in protein than pure grass hay"]'::jsonb,'Its nutritional content varies significantly depending on species ratio, cutting, and growing conditions','health','equine-nutrition','medium',null,'Correct. Mixed hay''s nutritional profile depends on the species ratio in that specific batch — which cannot be estimated visually. Testing each new load is especially important for horses with metabolic requirements.','Mixed hay''s nutritional content varies between loads, farms, and seasons based on species ratio and growing conditions. For horses with metabolic conditions, testing each load is essential because visual similarity to a prior batch does not guarantee similar NSC content.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_8a7af419102c','The maximum safe starch intake per meal for a horse is:','["0.5 kg per 100 kg of body weight","2 kg per 100 kg of body weight","1 kg per 100 kg of body weight","No limit if fed with adequate forage"]'::jsonb,'0.5 kg per 100 kg of body weight','health','equine-nutrition','medium',null,'Correct. Exceeding 0.5 kg of starch per 100 kg body weight per meal overwhelms the small intestine''s capacity and allows excess starch to reach the hindgut, causing fermentation problems.','The maximum safe starch intake is 0.5 kg per 100 kg body weight per meal. For a 500 kg horse, that is no more than 2.5 kg of starch per meal. Exceeding this risks hindgut acidosis.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_c7efa5d5a4d2','A ration balancer is best described as:','["A low-calorie, high-nutrient supplement that closes vitamin/mineral gaps in a forage-only diet","A complete feed replacement for hay in horses with dental problems","A high-energy concentrate for horses in hard work","A weight-gain product for underweight horses"]'::jsonb,'A low-calorie, high-nutrient supplement that closes vitamin/mineral gaps in a forage-only diet','health','equine-nutrition','medium',null,'Correct. A ration balancer provides concentrated vitamins, minerals, and protein without significant caloric load — ideal for horses at maintenance that need nutritional completion without added energy.','A ration balancer provides concentrated vitamins, minerals, and protein without significant calories. It is used to close nutritional gaps in forage-based diets for horses that do not need additional energy.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_04fe9e357046','Adding supplements to a horse already receiving a fortified concentrate at the manufacturer''s recommended rate is most likely to:','["Create nutrient imbalances, particularly with fat-soluble vitamins and minerals like selenium","Improve the horse''s overall nutritional status","Compensate for poor-quality hay in the diet","Have no effect — supplemental nutrients are always beneficial"]'::jsonb,'Create nutrient imbalances, particularly with fat-soluble vitamins and minerals like selenium','health','equine-nutrition','medium',null,'Correct. Fortified feeds are formulated to meet nutritional needs at the recommended rate. Adding supplements on top can cause excess accumulation — especially of fat-soluble vitamins and selenium.','Fortified concentrates are formulated to supply vitamins and minerals at the feeding rate. Adding supplements on top creates the risk of nutrient excess — especially fat-soluble vitamins (A, D, E, K) and selenium, which is toxic in overdose.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_a42fd0b2dd98','Which type of horse is LEAST likely to need grain concentrate added to its diet?','["A healthy adult horse at pasture rest in light or no work","A Thoroughbred mare in the last trimester of pregnancy","A horse in moderate daily training","A young horse being prepared for first-year showing"]'::jsonb,'A healthy adult horse at pasture rest in light or no work','health','equine-nutrition','medium',null,'Correct. An adult horse at rest or in light work on good-quality forage typically maintains appropriate body condition on forage alone. Adding concentrate without evaluating need wastes money and increases metabolic risk.','Horses at rest or in very light work typically maintain appropriate condition on forage alone. Concentrate is added to close an energy or protein gap — which rarely exists for horses doing little or no work on quality hay.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_87441440a2c9','Why is corn considered higher-risk than oats as an equine grain?','["Corn has nearly twice the starch density of oats and no fibrous hull to slow digestion","Corn is more likely to be contaminated with mold than oats","Corn provides lower energy density and is less digestible than oats","Corn requires soaking before feeding to make it safe for horses"]'::jsonb,'Corn has nearly twice the starch density of oats and no fibrous hull to slow digestion','health','equine-nutrition','medium',null,'Correct. Corn is very high in starch density and lacks the fibrous hull that slows oat starch digestion. This increases the risk of excess starch reaching the hindgut.','Corn has nearly twice the starch density of oats and lacks the fibrous hull that moderates oat starch absorption. This makes corn higher risk for hindgut starch overload at equivalent feeding rates.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_3f4db830b150','What is the primary reason supplement claims for horses should be evaluated skeptically?','["The equine supplement industry is largely unregulated, and few products have peer-reviewed efficacy data","Most supplements are harmful to horses and should be avoided entirely","Supplement companies are required to prove efficacy before selling products","All supplemental nutrients are available at lower cost through additional grain"]'::jsonb,'The equine supplement industry is largely unregulated, and few products have peer-reviewed efficacy data','health','equine-nutrition','medium',null,'Correct. Unlike veterinary medications, equine supplements do not require proof of efficacy before reaching the market. Evaluating a supplement requires reviewing published peer-reviewed research, not marketing claims.','The equine supplement industry is largely unregulated. Products do not require efficacy proof before sale. Evaluating a supplement requires examining published peer-reviewed research in horses — not testimonials or manufacturer claims.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_c7c19d91cc85','Which is the FIRST step in building a complete feeding program for a horse?','["Assess the horse — body weight, BCS, dentition, workload, and life stage","Select the concentrate product","Calculate how much hay to feed","Purchase a forage analysis kit"]'::jsonb,'Assess the horse — body weight, BCS, dentition, workload, and life stage','health','equine-nutrition','medium',null,'Correct. Building a feeding program starts with the horse, not the feed room. Body condition, life stage, workload, and dental status all determine what the horse needs before any product is chosen.','The feeding program begins with assessing the horse: body condition score, body weight, dental status, workload, and life stage. These determine what the horse actually needs — feed selection comes after that assessment.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_3ab832f0203e','The Henneke Body Condition Score system evaluates fat deposits at:','["Six locations: neck, withers, shoulder, ribs, loin, and tailhead","Four locations: ribs, back, haunches, and neck","Eight locations across the entire body surface","Only one location — the ribcage"]'::jsonb,'Six locations: neck, withers, shoulder, ribs, loin, and tailhead','health','equine-nutrition','medium',null,'Correct. The Henneke BCS system evaluates fat deposits at six specific anatomical locations, each reflecting where horses predictably store or lose fat in response to energy status.','The Henneke BCS system assesses fat at six locations: neck, withers, shoulder, ribs, loin, and tailhead. These locations were selected because horses deposit and lose fat in predictable patterns at each site.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_7c95308706d1','What does a Henneke BCS of 3 indicate?','["Thin — visible bone structure, slight fat cover on ribs, requiring dietary increase","Ideal body condition — appropriate for all horses","Moderately fleshy — appropriate for horses in moderate work","Obese — dietary restriction required"]'::jsonb,'Thin — visible bone structure, slight fat cover on ribs, requiring dietary increase','health','equine-nutrition','medium',null,'Correct. A BCS of 3 is described as thin — visible bone structure, ribs easily palpated with minimal fat cover. A horse at 3 requires increased caloric intake to reach the target of 5–6.','A BCS of 3 indicates a thin horse — visible bone structure and ribs easily felt with minimal fat cover. The target for most adult horses is BCS 5–6, so a score of 3 warrants dietary increase.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_943c8491ca3a','What does forage analysis provide that visual assessment cannot?','["Quantitative data on crude protein, digestible energy, NSC, and mineral content","Information about the hay''s smell and texture","A comparison of leaf-to-stem ratios","The identity of the grass or legume species in the hay"]'::jsonb,'Quantitative data on crude protein, digestible energy, NSC, and mineral content','health','equine-nutrition','medium',null,'Correct. Forage analysis provides the actual measured values for all key nutrients — none of which can be reliably estimated from appearance, smell, or texture.','Forage analysis provides the quantitative nutritional data needed for accurate ration balancing: crude protein, digestible energy, NSC, ADF, NDF, and minerals. These values cannot be estimated visually.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_6739ce1a0879','What is the minimum recommended transition period when changing a horse''s diet?','["10–14 days minimum","24–48 hours","3–4 days","One week only if switching to a completely different feed type"]'::jsonb,'10–14 days minimum','health','equine-nutrition','medium',null,'Correct. The hindgut microbiome needs 10–14 days minimum to adjust to a new feed substrate. Faster changes disrupt microbial populations and increase colic risk.','Dietary changes should occur over a minimum of 10–14 days. This allows the hindgut microbiome to adapt to the new substrate without the disruption that causes gas, colic, or hindgut acidosis.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_b6251c1a80ca','A horse''s body condition should ideally be monitored:','["Every 2–4 weeks — feeding programs require ongoing monitoring and adjustment","Once per year at the annual veterinary exam","Only when a problem is suspected","Immediately after each feeding session"]'::jsonb,'Every 2–4 weeks — feeding programs require ongoing monitoring and adjustment','health','equine-nutrition','medium',null,'Correct. A feeding program is not set-and-forget. BCS should be evaluated every 2–4 weeks, body weight monthly. Seasonal changes and workload changes both affect requirements.','BCS monitoring every 2–4 weeks and body weight checks monthly allow the feeding program to be adjusted before the horse reaches under- or over-condition. Feeding programs require ongoing management, not one-time calibration.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_15f79595d0c0','Why does life stage affect nutritional requirements more than any other single variable?','["Energy demands vary dramatically between life stages — a lactating mare may need double the energy of the same mare at maintenance","Older horses always require less nutrition than younger horses","Life stage determines a horse''s preference for hay vs. grain","Horses at different life stages have different water requirements only"]'::jsonb,'Energy demands vary dramatically between life stages — a lactating mare may need double the energy of the same mare at maintenance','health','equine-nutrition','medium',null,'Correct. Life stage produces the most dramatic variation in nutritional requirements. A lactating mare at peak production may need nearly double the energy of the same mare at maintenance — a greater difference than any workload category.','Life stage produces the greatest variation in nutritional requirements. A mare at peak lactation may need double the digestible energy of the same mare at maintenance — more than any other management variable drives nutritional needs.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_5ab6e0f3fb61','A horse losing weight on a ration that previously maintained it should first be evaluated for:','["Changes in forage quality, dental condition, workload, and health status","Addition of a supplement to increase caloric intake","Increased grain to compensate for the weight loss","Reduced activity to decrease energy expenditure"]'::jsonb,'Changes in forage quality, dental condition, workload, and health status','health','equine-nutrition','medium',null,'Correct. Weight loss in a horse on a previously adequate ration most commonly reflects a change in one of four variables: forage quality has changed, dental problems are reducing chewing efficiency, workload has increased, or a health condition is affecting nutrient utilization.','A horse losing weight on a previously adequate ration is not necessarily receiving too little feed. Forage quality may have changed between loads, dental problems may be reducing chewing efficiency, workload may have increased, or a health condition may be affecting nutrient utilization.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_51c0fda3317e','Colic in horses is best described as:','["Abdominal pain — a symptom with many possible causes","A specific intestinal disease caused by bacterial infection","Pain from grain overfeeding only","A chronic condition requiring ongoing medication"]'::jsonb,'Abdominal pain — a symptom with many possible causes','health','equine-nutrition','medium',null,'Correct. Colic is abdominal pain, not a specific diagnosis. It encompasses dozens of distinct conditions from mild gas to life-threatening intestinal displacement.','Colic is abdominal pain — a symptom, not a specific disease. It can range from mild gas discomfort that resolves with walking to life-threatening intestinal displacement requiring emergency surgery.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_5865b9e08f54','Which sign indicates that a colicky horse requires emergency veterinary attention?','["Continuous, unrelenting rolling, heart rate above 60 bpm, or pale mucous membranes","Mild pawing that stops when the horse is walked","Reluctance to eat hay but drinking water normally","Looking at the flank once or twice in an hour"]'::jsonb,'Continuous, unrelenting rolling, heart rate above 60 bpm, or pale mucous membranes','health','equine-nutrition','medium',null,'Correct. These signs indicate systemic distress rather than mild discomfort — they suggest conditions that may require surgery and cannot wait for conservative management.','Continuous rolling, elevated heart rate above 60 bpm, and pale or white mucous membranes are signs of systemic distress that require emergency veterinary response, not extended home management.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_8382074783bb','What is laminitis, and why is it a time-critical emergency?','["Inflammation of the laminae inside the hoof — the coffin bone can rotate or sink within 24–48 hours without intervention","A systemic infection of the horse''s hooves requiring antibiotic treatment","Inflammation of the hoof wall from repeated impact on hard ground","Seasonal hoof cracking caused by dry conditions"]'::jsonb,'Inflammation of the laminae inside the hoof — the coffin bone can rotate or sink within 24–48 hours without intervention','health','equine-nutrition','medium',null,'Correct. Laminitis disrupts blood flow and structural integrity of the laminae connecting the coffin bone to the hoof wall. Without prompt intervention, coffin bone rotation or sinking can cause permanent, career-ending damage.','Laminitis is inflammation of the laminar tissue connecting the coffin bone to the inner hoof wall. The coffin bone can rotate or sink within 24–48 hours of the inflammatory event — making early recognition and immediate veterinary contact essential.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_1c1befd6a5a1','The primary feed-related trigger for laminitis is:','["Carbohydrate overload — excess starch or sugar from grain or lush pasture","High protein intake from legume hay","Vitamin A deficiency from poor-quality hay","Feeding grain more than twice daily"]'::jsonb,'Carbohydrate overload — excess starch or sugar from grain or lush pasture','health','equine-nutrition','medium',null,'Correct. Carbohydrate overload (grain founder, pasture founder) is the primary feed-related trigger for laminitis. Excess NSC floods the hindgut, disrupting fermentation and triggering the vascular changes in the hoof laminae.','The primary feed-related laminitis trigger is carbohydrate overload: excess starch from grain or high-sugar pasture intake. The NSC-driven hindgut disruption produces systemic effects that compromise blood flow to the laminae.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_10810dd94cef','Early signs of laminitis include:','["Increased digital pulse at the fetlock, heat in the hooves, and a rocked-back stance","Coughing and nasal discharge","Fever and lymph node swelling","Reluctance to eat and sudden weight loss"]'::jsonb,'Increased digital pulse at the fetlock, heat in the hooves, and a rocked-back stance','health','equine-nutrition','medium',null,'Correct. Increased digital pulse, hoof heat, and the characteristic weight-shifted-back stance are the classic early indicators of laminitis — recognizable before radiographic rotation is present.','Early laminitis signs are increased digital pulse (palpable at the back of the fetlock), heat in the hooves, and a rocked-back stance that unloads the toes. These signs precede radiographic rotation and are the window for most effective intervention.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_77bfe367bca2','Choke in a horse differs from choking in a human because:','["Equine choke is esophageal obstruction — the horse can still breathe","Equine choke requires the Heimlich maneuver to resolve","Equine choke blocks both the esophagus and trachea simultaneously","Choke in horses is rarely serious and resolves without veterinary care"]'::jsonb,'Equine choke is esophageal obstruction — the horse can still breathe','health','equine-nutrition','medium',null,'Correct. Equine choke is a blockage in the esophagus, not the trachea. The horse can still breathe — but cannot swallow, and the risk is aspiration pneumonia, not immediate suffocation.','Equine choke is esophageal obstruction — material lodged in the esophagus, not the airway. A horse in choke can still breathe. The danger is aspiration pneumonia from material entering the airway during repeated swallowing attempts.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_4a395a67ecaa','What is the primary cause of Equine Gastric Ulcer Syndrome (EGUS)?','["Prolonged periods without forage, exposing the stomach''s squamous mucosa to continuously produced acid","Bacterial infection of the stomach lining","High-concentrate diets that increase stomach acid production","Rapid feed changes that alter stomach pH temporarily"]'::jsonb,'Prolonged periods without forage, exposing the stomach''s squamous mucosa to continuously produced acid','health','equine-nutrition','medium',null,'Correct. The horse''s stomach produces acid continuously. Without forage to buffer it, the squamous mucosa is exposed to acid damage. Extended fasting periods are the primary cause.','EGUS is caused by continuous stomach acid production in the absence of forage buffering. The squamous mucosa of the upper stomach is exposed to acid damage during any extended fasting period — making continuous forage access the primary prevention.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_fdf8956b43b3','Which management practice is the single most effective prevention for gastric ulcers?','["Continuous or near-continuous forage access to buffer stomach acid","Feeding concentrate three times daily instead of two","Providing salt blocks to encourage water intake","Administering antacids daily during heavy training periods"]'::jsonb,'Continuous or near-continuous forage access to buffer stomach acid','health','equine-nutrition','medium',null,'Correct. Continuous forage access eliminates the periods of unprotected acid exposure that cause mucosal damage. It is more effective and more sustainable than any supplement or medication-based prevention.','Continuous forage access is the most effective prevention for EGUS. It eliminates the extended acid exposure periods that damage the stomach lining. Small-hole hay nets, slow feeders, or round bales support this management approach.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_651d5067c265','Why is it important to minimize fasting periods during transport for horses at risk for gastric ulcers?','["The stomach produces acid continuously — fasting during transport exposes the mucosa to acid damage for extended periods","Transport stress reduces hindgut motility, requiring increased forage to maintain transit","Fasting during transport causes dehydration that increases colic risk","Transport vibration disrupts normal gastric emptying, making fasting during transport safer"]'::jsonb,'The stomach produces acid continuously — fasting during transport exposes the mucosa to acid damage for extended periods','health','equine-nutrition','medium',null,'Correct. The acid production mechanism does not pause during transport. A horse that has been without hay for six or more hours during a long haul has had prolonged acid exposure — a significant ulcer risk factor for performance horses.','The horse''s stomach produces acid whether or not the horse is moving. A haul that lasts several hours without hay provision means extended unprotected acid exposure — a documented risk factor for EGUS in performance horses.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_ffad917593ae','The most common feeding errors that produce colic or laminitis include:','["Large grain meals, insufficient forage, and dietary changes made too quickly","Feeding high-quality legume hay at the recommended rate","Providing continuous forage access rather than scheduled meals","Feeding concentrate in small, frequent meals rather than one large meal"]'::jsonb,'Large grain meals, insufficient forage, and dietary changes made too quickly','health','equine-nutrition','medium',null,'Correct. These three management errors account for a large proportion of preventable colic and laminitis cases. Horses that develop these conditions often have a feeding change or overfeeding event in the preceding 24–48 hours.','Large grain meals, inadequate forage, and rapid dietary changes are the three most common management factors preceding colic and laminitis events. All three are preventable through systematic feeding management.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_c4de90de6eab','Why is routine grooming considered essential daily horse care?','["It improves the horse''s appearance for shows","It maintains skin health, supports circulation, and provides a daily opportunity to inspect the horse","It replaces the need for veterinary check-ups","It is required by all equestrian organizations"]'::jsonb,'It maintains skin health, supports circulation, and provides a daily opportunity to inspect the horse','barn management','grooming-horses','medium',null,'Correct.','Not quite. The correct answer is It maintains skin health, supports circulation, and provides a daily opportunity to inspect the horse.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_cee84d497d36','What is the primary reason a horse should be groomed before riding?','["To make the horse look presentable","To remove debris under the saddle and girth that would cause rubs and sores during work","To calm the horse before training","To check the horse''s weight"]'::jsonb,'To remove debris under the saddle and girth that would cause rubs and sores during work','barn management','grooming-horses','medium',null,'Correct.','Not quite. The correct answer is To remove debris under the saddle and girth that would cause rubs and sores during work.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_2c14fa2651d6','How does grooming help a horse''s blood flow?','["By warming the coat with friction","Currying helps increase blood flow near the skin","By lowering the horse''s heart rate","Grooming does not affect blood flow"]'::jsonb,'Currying helps increase blood flow near the skin','barn management','grooming-horses','medium',null,'Correct.','Not quite. The correct answer is Currying helps increase blood flow near the skin.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
