insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_34d2dc247aa3','Why do domestic horses need regular grooming when wild horses do not?','["Domestic horses have weaker immune systems","Domestication has changed the horse''s coat type","Domestic horses lose access to mutual grooming, rolling, and natural weather exposure that wild horses use for coat care","Domestic horses are kept in warmer environments"]'::jsonb,'Domestic horses lose access to mutual grooming, rolling, and natural weather exposure that wild horses use for coat care','barn management','grooming-horses','medium',null,'Correct.','Not quite. The correct answer is Domestic horses lose access to mutual grooming, rolling, and natural weather exposure that wild horses use for coat care.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_dd198cfaae79','A horse pulls away and pins its ears whenever a specific spot on its back is brushed. What does this most likely indicate?','["The horse dislikes grooming in general","The horse is poorly trained","The horse may have pain or sensitivity at that location","The brush being used is the wrong type"]'::jsonb,'The horse may have pain or sensitivity at that location','barn management','grooming-horses','medium',null,'Correct.','Not quite. The correct answer is The horse may have pain or sensitivity at that location.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
