insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_a2f7f74a639f','Why should each horse have its own grooming kit where possible?','["It is easier to organize the barn","Sharing grooming tools between horses can spread skin conditions","Horses prefer the smell of their own tools","It prevents theft"]'::jsonb,'Sharing grooming tools between horses can spread skin conditions','barn management','grooming-horses','medium',null,'Correct.','Not quite. The correct answer is Sharing grooming tools between horses can spread skin conditions.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
