insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_41e1e4fac636','Which areas should the rubber curry comb NOT be used on?','["The barrel and hindquarters","The neck and shoulders","The legs, face, and bones","The back and body"]'::jsonb,'The legs, face, and bones','barn management','grooming-horses','medium',null,'Correct.','Not quite. The correct answer is The legs, face, and bones.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
