insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_e0537262948b','How does consistent chewing of forage help prevent gastric ulcers?','["Hay coats the stomach lining directly","Chewing produces saliva containing bicarbonate, which neutralizes gastric acid","Forage physically scrubs the stomach lining","Consistent chewing reduces overall acid production"]'::jsonb,'Chewing produces saliva containing bicarbonate, which neutralizes gastric acid','health','intro-to-feeding-nutrition','easy',null,'Correct.','Not quite. The correct answer is Chewing produces saliva containing bicarbonate, which neutralizes gastric acid.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
