insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_756654589b0e','What is a volte?','["A small circle, usually about 6 meters across","A large 20-meter circle","A straight line across the arena","A series of loops in an S shape"]'::jsonb,'A small circle, usually about 6 meters across','movement','arena-figures-school-movements','medium',null,'Correct. A volte is a small circle, about 6 meters across. Its small size asks for more bend and balance.','A volte is a small circle, usually about 6 meters across.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
