insert into questions (id, question, options, correct_answer, category, course_id, difficulty, image_url, explanation_correct, explanation_incorrect) values ('q_c38f648ea2dc','Why is checking tack a part of horse care?','["It protects the horse, the handler, and the gear","It feeds the horse","It trains the horse to jump","It changes the horse''s breed"]'::jsonb,'It protects the horse, the handler, and the gear','tack & equipment','tack-fundamentals-fit','medium',null,'Correct. A check guards comfort, safety, and the life of the tack.','Checking tack protects the horse, the handler, and the gear.') on conflict (id) do update set question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer, category=excluded.category, course_id=excluded.course_id, difficulty=excluded.difficulty, image_url=excluded.image_url, explanation_correct=excluded.explanation_correct, explanation_incorrect=excluded.explanation_incorrect;
